    #[cfg(any(target_os = "linux", target_os = "macos", windows))]
    fn assert_watcher_initial_reconciliation(
        edit_before_start: bool,
        initial_mode: FirstSliceIndexMode,
    ) {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let fixture = durable_test_tempdir();
        fs::create_dir(fixture.path().join("src")).expect("source directory exists");
        let source = fixture.path().join("src/lib.rs");
        fs::write(&source, "pub fn answer() -> u32 { 1 }\n").expect("initial source writes");
        let cancellation = Cancellation::with_deadline(Instant::now() + Duration::from_secs(30));
        let mut service = if initial_mode == FirstSliceIndexMode::Structural {
            FirstSliceService::new_durable_with_project_analyzer(
                8,
                paths.state_dir(),
                Arc::new(SuccessfulSemanticAnalyzer {
                    calls: Arc::new(AtomicUsize::new(0)),
                    identity: content_hash(b"watcher-semantic-analyzer"),
                }),
                &cancellation,
            )
        } else {
            FirstSliceService::new_durable(8, paths.state_dir(), &cancellation)
        }
        .expect("durable service initializes");
        if initial_mode == FirstSliceIndexMode::Structural {
            assert!(service.deep_analysis_available());
        }
        let initial = service
            .index_repository_with_mode(fixture.path(), initial_mode, &cancellation)
            .expect("initial generation publishes");
        let early_edit = "pub fn answer() -> u32 { 2 }\n";
        if edit_before_start {
            fs::write(&source, early_edit).expect("source changes before watcher startup");
        }
        let service = Arc::new(RwLock::new(service));

        let state = Arc::new(DaemonState::starting());
        state.set_catalog_status(HealthStatus::Healthy);
        let journal = Arc::new(OperationJournal::open_in_memory().expect("journal opens"));
        let actor =
            JournalActor::start_with_state(Arc::clone(&journal), 16, 16, Arc::clone(&state))
                .expect("journal actor starts");
        let handle = actor.handle();
        let (refinement, refinement_receiver) = mpsc::sync_channel(4);
        let lanes = FirstSliceServiceLanes {
            service: Arc::clone(&service),
            index_serialization: Arc::new(Mutex::new(())),
            semantic_refinements: Arc::new(Mutex::new(BTreeMap::new())),
            graph_projections: Arc::new(Mutex::new(GraphProjectionRegistry::new())),
            refinement,
            recovery_ready: Arc::new(AtomicBool::new(true)),
            recovery_complete: Arc::new(AtomicBool::new(true)),
            recovery_admission_ready: Arc::new(AtomicBool::new(true)),
            recovering_repositories: Arc::new(RwLock::new(BTreeMap::new())),
            recovery_demand: Arc::new(Mutex::new(RecoveryDemandQueue::default())),
            support_state: Some(Arc::clone(&state)),
        };
        let metadata = Arc::new(Mutex::new(OperationMetadataSet::new(32)));
        let stopping = Arc::new(AtomicBool::new(false));
        let watcher_cancellation = Cancellation::new();
        let worker_cancellation = watcher_cancellation.clone();
        let worker_stopping = Arc::clone(&stopping);
        let watcher = thread::spawn(move || {
            watcher_worker(
                lanes,
                worker_stopping,
                worker_cancellation,
                WatcherWorkerResources {
                    journal: handle,
                    metadata,
                    runtime: tokio::runtime::Builder::new_current_thread()
                        .enable_time()
                        .build()
                        .expect("watcher runtime builds"),
                    config: WatcherConfig {
                        poll_interval: Duration::from_millis(10),
                        debounce_interval: Duration::from_millis(10),
                        retry_interval: Duration::from_millis(10),
                        maximum_repository_entries: 1_000,
                    },
                    nonce: [91; 32],
                },
            )
        });
        let control = ControlService::with_state(
            Arc::clone(&journal),
            [92; 16],
            Arc::clone(&state),
            DaemonLimits::default(),
        );

        wait_for_watcher_status(&control, HealthStatus::Healthy);
        if initial_mode == FirstSliceIndexMode::Structural && !edit_before_start {
            stopping.store(true, Ordering::Release);
            let _ = watcher_cancellation.cancel(CancellationReason::Shutdown);
            watcher
                .join()
                .expect("watcher thread joins")
                .expect("watcher exits cleanly");
            actor.join().expect("journal actor joins");
            assert_eq!(
                service
                    .read()
                    .expect("service remains available")
                    .active_generation_for(initial.repository),
                Some(initial.generation)
            );
            assert!(
                refinement_receiver.try_recv().is_err(),
                "unchanged watcher reconciliation must not queue a semantic upgrade"
            );
            return;
        }
        if edit_before_start {
            stopping.store(true, Ordering::Release);
            let _ = watcher_cancellation.cancel(CancellationReason::Shutdown);
            watcher
                .join()
                .expect("watcher thread joins")
                .expect("watcher exits cleanly");
            actor.join().expect("journal actor joins");
            let service = service.read().expect("service remains available");
            let generation = service
                .active_generation_for(initial.repository)
                .expect("repository retains an active generation");
            assert_ne!(
                generation, initial.generation,
                "first observation must reconcile changes after indexing"
            );
            if initial_mode == FirstSliceIndexMode::Structural {
                let refinement = refinement_receiver
                    .try_recv()
                    .expect("changed sources retain automatic semantic refinement");
                assert_eq!(refinement.repository, initial.repository);
                assert_eq!(refinement.structural_generation, generation);
            }
            let located = service
                .code_locate_with_entity_filters_and_budget(
                    generation,
                    "src/lib.rs".to_owned(),
                    LocateMode::Prefix,
                    Vec::new(),
                    vec!["src/lib.rs".to_owned()],
                    Some(vec!["file".to_owned()]),
                    1,
                    0,
                    FirstSliceBudget::default(),
                    &cancellation,
                )
                .expect("edited file locates in the published generation");
            assert_eq!(located.data.hits.len(), 1);
            let source_ref = located.data.hits[0]
                .source
                .clone()
                .expect("edited source remains indexed");
            let read = service
                .source_read(generation, vec![source_ref], &cancellation)
                .expect("edited generation source is readable");
            assert_eq!(read.data.chunks.len(), 1);
            assert_eq!(read.data.chunks[0].bytes, early_edit.as_bytes());
            return;
        }
        wait_for_watcher_operations(&journal, initial.repository, 1);
        let contexts = journal
            .repository_operation_contexts()
            .expect("repository contexts remain readable");
        assert_eq!(contexts.len(), 1);
        assert_eq!(contexts[0].published_generation, Some(initial.generation));
        let evidence = contexts[0]
            .evidence
            .as_ref()
            .expect("initial reconciliation retains work evidence");
        assert_eq!(
            evidence.build_strategy,
            RepositoryBuildStrategy::RetainedGeneration
        );
        assert_eq!(evidence.changed_files, 0);
        assert_eq!(evidence.rebuilt_files, 0);
        assert_eq!(evidence.rebuilt_facts, 0);
        assert_eq!(
            service
                .read()
                .expect("service remains available")
                .active_generation_for(initial.repository),
            Some(initial.generation)
        );

        fs::write(&source, "pub fn answer() -> u64 { 200 }\n").expect("source edit writes");
        let edited = wait_for_watcher_generation(&service, initial.repository, initial.generation);

        let added_source = fixture.path().join("src/added.rs");
        fs::write(&added_source, "pub fn added() -> bool { true }\n").expect("added source writes");
        let added = wait_for_watcher_generation(&service, initial.repository, edited);

        fs::remove_file(&added_source).expect("added source deletes");
        let deleted = wait_for_watcher_generation(&service, initial.repository, added);
        assert_ne!(deleted, added);
        wait_for_watcher_operations(&journal, initial.repository, 4);
        assert_eq!(control.health().watcher_status, HealthStatus::Healthy);

        stopping.store(true, Ordering::Release);
        let _ = watcher_cancellation.cancel(CancellationReason::Shutdown);
        watcher
            .join()
            .expect("watcher thread joins")
            .expect("watcher exits cleanly");
        actor.join().expect("journal actor joins");
    }

    #[test]
    fn resource_pressure_classification_is_bounded_and_monotonic() {
        let gibibyte = 1024 * 1024 * 1024;
        let total = 16 * gibibyte;

        assert_eq!(
            classify_resource_pressure(0, 0, 0),
            ResourcePressure::Unknown
        );
        assert_eq!(
            classify_resource_pressure(total, 8 * gibibyte, gibibyte),
            ResourcePressure::Normal
        );
        assert_eq!(
            classify_resource_pressure(total, 3 * gibibyte, 8 * gibibyte),
            ResourcePressure::Elevated
        );
        assert_eq!(
            classify_resource_pressure(total, gibibyte, 11 * gibibyte),
            ResourcePressure::High
        );
        assert_eq!(
            classify_resource_pressure(total, gibibyte / 2, 13 * gibibyte),
            ResourcePressure::Critical
        );
    }

