    #[test]
    fn syntax_fact_recovery_splits_once_then_selects_a_scoped_file() {
        let repository = RepositoryId::from_bytes([31; 16]);
        let generation = GenerationId::from_bytes([32; 20]);
        let input = |file_byte: u8, path: &str| adapter::ProjectInput {
            file: Some(common::FileId {
                value: vec![file_byte; 20],
            }),
            path: path.to_owned(),
            language: "php".to_owned(),
            source_digest: Some(common::ContentHash {
                value: vec![file_byte; 32],
            }),
            source: b"<?php\n".to_vec(),
            generated: false,
            origins: Vec::new(),
        };
        let inputs = vec![input(1, "src/first.php"), input(2, "src/second.php")];
        let mut document = NormalizedIrDocument::empty(repository, generation);
        document.diagnostics.push(DiagnosticRecord {
            id: FactId::from_bytes([33; 20]),
            repository,
            generation,
            code: PROJECT_SYNTAX_FACT_LIMIT_DIAGNOSTIC.to_owned(),
            message: "bounded syntax fixture".to_owned(),
            severity: DiagnosticSeverity::Warning,
            source: Some(SourceRef::new(
                repository,
                generation,
                SourceSpan::new(FileId::from_bytes([2; 20]), 0, 6).expect("fixture span is valid"),
                ContentHash::from_bytes([2; 32]),
                None,
            )),
            coverage_effect: CoverageStatus::Bounded,
            provenance: FactId::from_bytes([34; 20]),
            evidence: FactEvidence {
                source: None,
                derivation: Vec::new(),
            },
        });

        assert!(project_partition_needs_syntax_split(&document, 2, 0));
        assert!(!project_partition_needs_syntax_split(&document, 2, 1));
        let limited = project_syntax_recovery_input(&document, &inputs)
            .expect("scoped recovery selection succeeds");
        assert_eq!(
            limited.as_ref().map(|input| input.path.as_str()),
            Some("src/second.php")
        );
        document.diagnostics[0].source = None;
        document.diagnostics[0].evidence.source = None;
        let mut implementation = input(3, "web/endpoints.go");
        implementation.source = b"func route() { handler() }\n".to_vec();
        let mut test = input(4, "web/endpoints_test.go");
        test.source = b"func test() { handler(); handler(); handler() }\n".to_vec();
        let limited = project_syntax_recovery_input(&document, &[implementation, test])
            .expect("unscoped recovery selection succeeds");
        assert_eq!(
            limited.as_ref().map(|input| input.path.as_str()),
            Some("web/endpoints.go")
        );
        assert!(
            project_syntax_recovery_input(&document, &inputs[1..])
                .expect("single input does not retry")
                .is_none()
        );
        document.diagnostics.clear();
        assert!(
            project_syntax_recovery_input(&document, &inputs)
                .expect("complete partitions do not retry")
                .is_none()
        );
    }

    #[test]
    fn project_partition_buffer_enforces_the_adapter_file_ceiling() {
        let mut buffer =
            ProjectPartitionBuffer::new(128, 8, 2).expect("partition buffer initializes");
        for file_byte in [1_u8, 2] {
            assert!(
                buffer
                    .try_push(adapter::ProjectInput {
                        file: Some(common::FileId {
                            value: vec![file_byte; 20],
                        }),
                        path: format!("Lib/{file_byte}.py"),
                        language: "python".to_owned(),
                        source_digest: Some(common::ContentHash {
                            value: vec![file_byte; 32],
                        }),
                        source: b"pass\n".to_vec(),
                        generated: false,
                        origins: Vec::new(),
                    })
                    .expect("input is measurable")
                    .is_none()
            );
        }
        assert!(
            buffer
                .try_push(adapter::ProjectInput {
                    file: Some(common::FileId { value: vec![3; 20] }),
                    path: "Lib/3.py".to_owned(),
                    language: "python".to_owned(),
                    source_digest: Some(common::ContentHash { value: vec![3; 32] }),
                    source: b"pass\n".to_vec(),
                    generated: false,
                    origins: Vec::new(),
                })
                .expect("input is measurable")
                .is_some()
        );
    }

    #[test]
    fn project_partition_buffer_batches_small_files_for_large_repositories() {
        let mut buffer =
            ProjectPartitionBuffer::new(128, 8, usize::MAX).expect("partition buffer initializes");
        for file_index in 0..PROJECT_ADAPTER_PARTITION_FILES {
            let encoded = u16::try_from(file_index)
                .expect("partition fixture index fits")
                .to_le_bytes();
            let file_id = encoded.repeat(10);
            let source_digest = encoded.repeat(16);
            assert!(
                buffer
                    .try_push(adapter::ProjectInput {
                        file: Some(common::FileId { value: file_id }),
                        path: format!("src/{file_index}.ts"),
                        language: "typescript".to_owned(),
                        source_digest: Some(common::ContentHash {
                            value: source_digest,
                        }),
                        source: b"export const value = 1;\n".to_vec(),
                        generated: false,
                        origins: Vec::new(),
                    })
                    .expect("input is measurable")
                    .is_none()
            );
        }
        assert_eq!(buffer.take().len(), PROJECT_ADAPTER_PARTITION_FILES);
    }

    #[test]
    fn project_adapter_failures_keep_their_public_resource_class() {
        assert_eq!(
            map_project_adapter_error(AdapterHostError::ProcessTimeout),
            FirstSliceProjectAnalysisError::WallTimeLimit
        );
        assert_eq!(
            map_project_adapter_error(AdapterHostError::ProjectOutputLimit),
            FirstSliceProjectAnalysisError::OutputLimit
        );
        assert_eq!(
            map_project_adapter_error(AdapterHostError::ProcessFailed),
            FirstSliceProjectAnalysisError::ProcessFailure
        );
        assert_eq!(
            map_project_adapter_error(AdapterHostError::ProcessResourceUnavailable),
            FirstSliceProjectAnalysisError::ResourceUnavailable
        );

        let operation = OperationId::from_bytes([17; 16]);
        let repository = RepositoryId::from_bytes([18; 16]);
        let context = RepositoryIndexErrorContext {
            operation,
            repository,
            provider: repository_index_provider(FirstSliceIndexMode::Deep),
        };
        let wall_time = repository_index_error(FirstSliceError::AdapterWallTimeLimit, context);

        assert_eq!(wall_time.code(), ErrorCode::ResourceExhausted);
        assert!(!wall_time.retryable());
        assert_eq!(wall_time.retry_after_ms(), None);
        assert_eq!(
            wall_time.details().get(&static_detail_key("resource")),
            Some(&PublicValue::Label(static_safe_label(
                "adapter_wall_time_ms"
            )))
        );
        assert_eq!(
            wall_time.details().get(&static_detail_key("limit")),
            Some(&PublicValue::Unsigned(PROJECT_ADAPTER_WALL_TIME_MS))
        );
        assert_eq!(
            wall_time
                .details()
                .get(&static_detail_key("structural_fallback")),
            Some(&PublicValue::Boolean(true))
        );
        assert_eq!(
            wall_time.next_actions(),
            &[
                NextAction::InspectOperation,
                NextAction::CollectSupportBundle,
            ]
        );

        let output = repository_index_error(FirstSliceError::AdapterOutputLimit, context);
        assert_eq!(output.code(), ErrorCode::ResourceExhausted);
        assert!(!output.retryable());
        assert_eq!(output.retry_after_ms(), None);
        assert_eq!(
            output.details().get(&static_detail_key("resource")),
            Some(&PublicValue::Label(static_safe_label(
                "adapter_output_bytes"
            )))
        );
        assert_eq!(
            output.details().get(&static_detail_key("limit")),
            Some(&PublicValue::Unsigned(PROJECT_ADAPTER_OUTPUT_BYTES))
        );
        assert_eq!(
            output
                .details()
                .get(&static_detail_key("structural_fallback")),
            Some(&PublicValue::Boolean(true))
        );
        assert_eq!(
            output.next_actions(),
            &[
                NextAction::InspectOperation,
                NextAction::CollectSupportBundle,
            ]
        );

        for bounded in [
            FirstSliceError::AdapterInputLimit,
            FirstSliceError::AdapterMemoryLimit,
        ] {
            let error = repository_index_error(bounded, context);
            assert_eq!(error.code(), ErrorCode::ResourceExhausted);
            assert!(!error.retryable());
            assert_eq!(error.retry_after_ms(), None);
            assert!(!error.next_actions().contains(&NextAction::Retry));
        }

        let unavailable = repository_index_error(
            FirstSliceError::ResourceUnavailable {
                resource: rootlight_service::FirstSliceResource::ProcessResources,
            },
            context,
        );
        assert_eq!(unavailable.code(), ErrorCode::ResourceExhausted);
        assert!(unavailable.retryable());
        assert_eq!(
            unavailable
                .details()
                .get(&static_detail_key("failure_stage")),
            Some(&PublicValue::Label(static_safe_label("analysis")))
        );
        assert_eq!(
            unavailable.details().get(&static_detail_key("resource")),
            Some(&PublicValue::Label(static_safe_label("process_resources")))
        );
        assert_eq!(
            unavailable.next_actions(),
            &[
                NextAction::InspectOperation,
                NextAction::CollectSupportBundle,
                NextAction::Retry,
            ]
        );
        assert_eq!(
            unavailable.retry_after_ms(),
            Some(u64::from(RETRY_AFTER_MS))
        );

        let process = repository_index_error(FirstSliceError::AdapterProcessFailure, context);
        assert_eq!(process.code(), ErrorCode::AdapterFailed);
        assert!(process.retryable());
        assert_eq!(
            process.details().get(&static_detail_key("resource")),
            Some(&PublicValue::Label(static_safe_label("adapter_process")))
        );
        assert_eq!(process.retry_after_ms(), Some(u64::from(RETRY_AFTER_MS)));

        let incomplete = repository_index_error(FirstSliceError::IncompleteCoverage, context);
        assert_eq!(incomplete.code(), ErrorCode::IncompleteCoverage);
        assert!(!incomplete.retryable());
        assert_eq!(
            incomplete
                .details()
                .get(&static_detail_key("structural_fallback")),
            Some(&PublicValue::Boolean(true))
        );
        assert_eq!(
            incomplete.next_actions(),
            &[
                NextAction::InspectOperation,
                NextAction::CollectSupportBundle,
            ]
        );
        assert!(!semantic_refinement_degrades_adapter(&incomplete));

        let discovery_incomplete = repository_index_error(
            FirstSliceError::DiscoveryIncomplete {
                resource: rootlight_service::FirstSliceResource::DiscoveryEntries,
                estimated: 100_001,
                limit: 100_000,
            },
            context,
        );
        assert_eq!(discovery_incomplete.code(), ErrorCode::IncompleteCoverage);
        assert!(!discovery_incomplete.retryable());
        assert_eq!(
            discovery_incomplete
                .details()
                .get(&static_detail_key("resource")),
            Some(&PublicValue::Label(static_safe_label("discovery_entries")))
        );
        assert_eq!(
            discovery_incomplete
                .details()
                .get(&static_detail_key("estimated")),
            Some(&PublicValue::Unsigned(100_001))
        );
        assert_eq!(
            discovery_incomplete
                .details()
                .get(&static_detail_key("active_generation_preserved")),
            Some(&PublicValue::Boolean(true))
        );
        assert_eq!(
            discovery_incomplete.next_actions(),
            &[
                NextAction::InspectOperation,
                NextAction::UpdateConfiguration {
                    key: static_safe_label("analysis.max_discovery_entries"),
                },
            ]
        );

        let source_incomplete = repository_index_error(
            FirstSliceError::DiscoveryIncomplete {
                resource: rootlight_service::FirstSliceResource::SourceBytes,
                estimated: 537_000_000,
                limit: 536_870_912,
            },
            context,
        );
        assert_eq!(source_incomplete.code(), ErrorCode::IncompleteCoverage);
        assert_eq!(
            source_incomplete
                .details()
                .get(&static_detail_key("resource")),
            Some(&PublicValue::Label(static_safe_label("source_bytes")))
        );
        assert_eq!(
            source_incomplete
                .details()
                .get(&static_detail_key("active_generation_preserved")),
            Some(&PublicValue::Boolean(true))
        );
        assert_eq!(
            source_incomplete.next_actions(),
            &[
                NextAction::InspectOperation,
                NextAction::CollectSupportBundle,
            ]
        );

        let declaration_loss = repository_index_error(
            FirstSliceError::ProjectCoverageIncomplete {
                language: FirstSliceProjectCoverageLanguage::Java,
                reason: FirstSliceProjectCoverageReason::StructuralDeclarationLoss,
                missing_declarations: 1_584,
            },
            context,
        );
        assert_eq!(declaration_loss.code(), ErrorCode::IncompleteCoverage);
        assert!(!declaration_loss.retryable());
        assert_eq!(
            declaration_loss
                .details()
                .get(&static_detail_key("language")),
            Some(&PublicValue::Label(static_safe_label("java")))
        );
        assert_eq!(
            declaration_loss
                .details()
                .get(&static_detail_key("coverage_reason")),
            Some(&PublicValue::Label(static_safe_label(
                "structural_declaration_loss"
            )))
        );
        assert_eq!(
            declaration_loss
                .details()
                .get(&static_detail_key("missing_declarations")),
            Some(&PublicValue::Unsigned(1_584))
        );
        assert_eq!(
            declaration_loss
                .details()
                .get(&static_detail_key("structural_fallback")),
            Some(&PublicValue::Boolean(true))
        );
        assert_eq!(
            declaration_loss.next_actions(),
            &[
                NextAction::InspectOperation,
                NextAction::CollectSupportBundle,
            ]
        );
        assert!(!semantic_refinement_degrades_adapter(&declaration_loss));

        let facts_truncated = repository_index_error(
            FirstSliceError::ProjectCoverageIncomplete {
                language: FirstSliceProjectCoverageLanguage::TypeScript,
                reason: FirstSliceProjectCoverageReason::FactsTruncated,
                missing_declarations: 0,
            },
            context,
        );
        assert_eq!(facts_truncated.code(), ErrorCode::IncompleteCoverage);
        assert_eq!(
            facts_truncated
                .details()
                .get(&static_detail_key("language")),
            Some(&PublicValue::Label(static_safe_label("typescript")))
        );
        assert_eq!(
            facts_truncated
                .details()
                .get(&static_detail_key("coverage_reason")),
            Some(&PublicValue::Label(static_safe_label(
                "project_facts_truncated"
            )))
        );
        assert_eq!(
            facts_truncated
                .details()
                .get(&static_detail_key("missing_declarations")),
            Some(&PublicValue::Unsigned(0))
        );
        assert!(!semantic_refinement_degrades_adapter(&facts_truncated));

        let normalized_capacity = repository_index_error(
            FirstSliceError::ResourceLimit {
                resource: rootlight_service::FirstSliceResource::Entities,
                observed: 3,
                limit: 2,
            },
            context,
        );
        assert_eq!(normalized_capacity.code(), ErrorCode::ResourceExhausted);
        assert_eq!(
            normalized_capacity
                .details()
                .get(&static_detail_key("failure_stage")),
            Some(&PublicValue::Label(static_safe_label("analysis")))
        );
        assert_eq!(
            normalized_capacity
                .details()
                .get(&static_detail_key("resource")),
            Some(&PublicValue::Label(static_safe_label("entities")))
        );
        assert_eq!(
            normalized_capacity
                .details()
                .get(&static_detail_key("observed")),
            Some(&PublicValue::Unsigned(3))
        );
        assert_eq!(
            normalized_capacity
                .details()
                .get(&static_detail_key("limit")),
            Some(&PublicValue::Unsigned(2))
        );
        assert!(semantic_refinement_degrades_adapter(&process));
    }

    #[test]
    fn repository_index_failures_retain_safe_operation_context() {
        let operation = OperationId::from_bytes([19; 16]);
        let repository = RepositoryId::from_bytes([23; 16]);
        let error = repository_index_error(
            FirstSliceError::Discovery,
            RepositoryIndexErrorContext {
                operation,
                repository,
                provider: repository_index_provider(FirstSliceIndexMode::Structural),
            },
        );

        assert_eq!(error.code(), ErrorCode::Internal);
        assert_eq!(error.operation(), Some(operation));
        assert_eq!(error.repository(), Some(repository));
        assert_eq!(
            error.details().get(&static_detail_key("failure_family")),
            Some(&PublicValue::Label(static_safe_label("discovery")))
        );
        assert_eq!(
            error.details().get(&static_detail_key("failure_stage")),
            Some(&PublicValue::Label(static_safe_label("discovery")))
        );
        assert_eq!(
            error.details().get(&static_detail_key("provider")),
            Some(&PublicValue::Label(static_safe_label(
                "rootlight-first-slice-treesitter"
            )))
        );
        assert_eq!(
            error.next_actions(),
            &[
                NextAction::InspectOperation,
                NextAction::CollectSupportBundle
            ]
        );

        let bounded = repository_index_error(
            FirstSliceError::ResourceLimit {
                resource: rootlight_service::FirstSliceResource::Extensions,
                observed: 10_001,
                limit: 10_000,
            },
            RepositoryIndexErrorContext {
                operation,
                repository,
                provider: repository_index_provider(FirstSliceIndexMode::Structural),
            },
        );
        assert_eq!(bounded.code(), ErrorCode::ResourceExhausted);
        assert!(!bounded.retryable());
        assert_eq!(
            bounded.details().get(&static_detail_key("resource")),
            Some(&PublicValue::Label(static_safe_label("extensions")))
        );
        assert_eq!(
            bounded.details().get(&static_detail_key("observed")),
            Some(&PublicValue::Unsigned(10_001))
        );
        assert_eq!(
            bounded.details().get(&static_detail_key("limit")),
            Some(&PublicValue::Unsigned(10_000))
        );
        assert_eq!(
            bounded.next_actions(),
            &[
                NextAction::InspectOperation,
                NextAction::CollectSupportBundle
            ]
        );

        let storage = repository_index_error(
            FirstSliceError::StorageResourceExhausted {
                scope: rootlight_service::FirstSliceStorageScope::Repository,
                required_bytes: 4096,
                observed_bytes: 8192,
                projected_bytes: 12_288,
                limit_bytes: 10_000,
                minimum_free_bytes: 1024,
                repository_amplification: None,
            },
            RepositoryIndexErrorContext {
                operation,
                repository,
                provider: repository_index_provider(FirstSliceIndexMode::Structural),
            },
        );
        assert_eq!(storage.code(), ErrorCode::ResourceExhausted);
        assert!(!storage.retryable());
        assert_eq!(
            storage.details().get(&static_detail_key("resource")),
            Some(&PublicValue::Label(static_safe_label(
                "repository_storage_bytes"
            )))
        );
        assert_eq!(
            storage.details().get(&static_detail_key("required_bytes")),
            Some(&PublicValue::Unsigned(4096))
        );
        assert_eq!(
            storage
                .details()
                .get(&static_detail_key("minimum_free_bytes")),
            Some(&PublicValue::Unsigned(1024))
        );

        let retention = build_service_error(FirstSliceError::Retention, None);
        assert_eq!(retention.code(), ErrorCode::ResourceExhausted);
        assert!(!retention.retryable());
        assert_eq!(retention.retry_after_ms(), None);
        assert_eq!(retention.next_actions(), &[]);

        let invalid_limits = build_service_error(FirstSliceError::Limits, None);
        assert_eq!(invalid_limits.code(), ErrorCode::Internal);
        assert!(!invalid_limits.retryable());
        assert_eq!(
            invalid_limits.next_actions(),
            &[NextAction::CollectSupportBundle]
        );

        let repository_capacity = build_service_error(
            FirstSliceError::RepositoryCapacityLimit {
                observed: 177,
                limit: 176,
                configuration: rootlight_service::FirstSliceRepositoryCapacityConfiguration::MaximumRepositories,
                pending_repositories: 0,
                reclaimable_repositories: 176,
            },
            None,
        );
        assert_eq!(
            repository_capacity
                .details()
                .get(&static_detail_key("failure_stage")),
            Some(&PublicValue::Label(static_safe_label("admission")))
        );
        assert_eq!(
            repository_capacity
                .details()
                .get(&static_detail_key("configuration_key")),
            Some(&PublicValue::Label(static_safe_label(
                "storage.maximum_repositories"
            )))
        );
        assert_eq!(
            repository_capacity.next_actions(),
            &[
                NextAction::CollectSupportBundle,
                NextAction::UpdateConfiguration {
                    key: static_safe_label("storage.maximum_repositories"),
                },
                NextAction::DeleteRepository,
            ]
        );

        let retention_bound = build_service_error(
            FirstSliceError::RepositoryCapacityLimit {
                observed: 177,
                limit: 176,
                configuration: rootlight_service::FirstSliceRepositoryCapacityConfiguration::RetainedGenerations,
                pending_repositories: 0,
                reclaimable_repositories: 176,
            },
            None,
        );
        assert_eq!(
            retention_bound
                .details()
                .get(&static_detail_key("configuration_key")),
            Some(&PublicValue::Label(static_safe_label(
                "storage.retained_generations"
            )))
        );

        let pending_capacity = build_service_error(
            FirstSliceError::RepositoryCapacityLimit {
                observed: 3,
                limit: 2,
                configuration: rootlight_service::FirstSliceRepositoryCapacityConfiguration::MaximumRepositories,
                pending_repositories: 2,
                reclaimable_repositories: 0,
            },
            None,
        );
        assert_eq!(pending_capacity.code(), ErrorCode::Busy);
        assert!(pending_capacity.retryable());
        assert_eq!(pending_capacity.next_actions(), &[NextAction::Retry]);
        assert_eq!(
            pending_capacity
                .details()
                .get(&static_detail_key("pending_repositories")),
            Some(&PublicValue::Unsigned(2))
        );
    }

