    #[test]
    fn generation_memory_limit_exposes_bounded_numeric_component_details() {
        let breakdown = rootlight_service::GenerationMemoryBreakdown {
            retained_bytes: 9,
            reserved_bytes: 8,
            owned_bytes: 9,
            referenced_bytes: 0,
            mapped_bytes: 0,
            staged_bytes: 0,
            shared_bytes: 0,
        };
        let error = build_service_error(
            FirstSliceError::GenerationMemoryLimit {
                breakdown,
                observed: 17,
                limit: 16,
            },
            None,
        );

        assert_eq!(error.code(), ErrorCode::ResourceExhausted);
        assert!(!error.retryable());
        assert_eq!(
            error.details().get(&static_detail_key("resource")),
            Some(&PublicValue::Label(static_safe_label(
                "generation_memory_bytes"
            )))
        );
        for (key, value) in [
            ("observed", 17),
            ("limit", 16),
            ("retained_memory_bytes", breakdown.retained_bytes),
            ("reserved_memory_bytes", breakdown.reserved_bytes),
            ("owned_memory_bytes", breakdown.owned_bytes),
            ("referenced_memory_bytes", breakdown.referenced_bytes),
            ("mapped_memory_bytes", breakdown.mapped_bytes),
            ("staged_memory_bytes", breakdown.staged_bytes),
            ("shared_memory_bytes", breakdown.shared_bytes),
        ] {
            assert_eq!(
                error.details().get(&static_detail_key(key)),
                Some(&PublicValue::Unsigned(value))
            );
        }
        assert_eq!(error.next_actions(), &[NextAction::CollectSupportBundle]);
    }

    #[test]
    fn clean_rebuild_preserves_deep_generation_and_auto_reuses_it() {
        assert_eq!(
            repository_index_plan_mode_tag(
                daemon::RepositoryIndexMode::RepositoryIndexRebuild,
                FirstSliceIndexMode::Structural,
            ),
            4
        );
        assert_ne!(
            repository_index_plan_mode_tag(
                daemon::RepositoryIndexMode::RepositoryIndexRebuild,
                FirstSliceIndexMode::Deep,
            ),
            repository_index_mode_tag(FirstSliceIndexMode::Deep)
        );
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let fixture = durable_test_tempdir();
        fs::create_dir(fixture.path().join("src")).expect("fixture source directory exists");
        fs::write(
            fixture.path().join("src/lib.rs"),
            "pub fn deep_noop() -> bool { true }\n",
        )
        .expect("fixture source writes");

        let calls = Arc::new(AtomicUsize::new(0));
        let analyzer: Arc<dyn FirstSliceProjectAnalyzer> = Arc::new(SuccessfulSemanticAnalyzer {
            calls: Arc::clone(&calls),
            identity: content_hash(b"daemon-successful-semantic-analyzer"),
        });
        let setup_deadline = Instant::now() + Duration::from_secs(30);
        let service = Arc::new(RwLock::new(
            FirstSliceService::new_durable_with_project_analyzer(
                3,
                paths.state_dir(),
                analyzer,
                &Cancellation::with_deadline(setup_deadline),
            )
            .expect("durable semantic service initializes"),
        ));
        let journal = Arc::new(
            OperationJournal::open(&paths.operation_journal_path())
                .expect("operation journal opens"),
        );
        let actor = JournalActor::start(Arc::clone(&journal), 8, 8).expect("journal actor starts");
        let handle = actor.handle();
        let metadata = Mutex::new(OperationMetadataSet::new(8));
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_time()
            .build()
            .expect("runtime builds");
        let resources = ServiceRequestResources {
            journal: &handle,
            metadata: &metadata,
            runtime: &runtime,
            catalog_epoch: Instant::now(),
            publication_hook: None,
        };
        let (refinement, refinement_receiver) = mpsc::sync_channel(1);
        let lanes = FirstSliceServiceLanes {
            service: Arc::clone(&service),
            index_serialization: Arc::new(Mutex::new(())),
            semantic_refinements: Arc::new(Mutex::new(BTreeMap::new())),
            graph_projections: Arc::new(Mutex::new(GraphProjectionRegistry::new())),
            refinement,
            recovery_ready: Arc::new(AtomicBool::new(true)),
            recovery_complete: Arc::new(AtomicBool::new(true)),
            recovery_admission_ready: Arc::new(AtomicBool::new(true)),
            recovering_repositories: Arc::new(RwLock::new(BTreeMap::new())),
            recovery_demand: Arc::new(Mutex::new(RecoveryDemandQueue::default())),
            support_state: None,
        };
        let root = fixture.path().to_string_lossy().into_owned();
        let context = |client: u8| {
            let deadline = Instant::now() + Duration::from_secs(30);
            FirstSliceIpcContext {
                client_instance_id: ClientInstanceId::from_bytes([client; 16]),
                selected_protocol_minor: rootlight_daemon_core::PROTOCOL_MINOR,
                cancellation: Cancellation::with_deadline(deadline),
                deadline,
                effective_budget: None,
                index_admission: None,
            }
        };

        let deep_operation = OperationId::from_bytes([116; 16]);
        let deep_context = context(116);
        let mut no_reply = None;
        let cold_error = repository_index(
            &lanes,
            resources,
            daemon::RepositoryIndexRequest {
                schema_version: Some(schema_version()),
                root: root.clone(),
                operation: Some(operation_to_wire(OperationId::from_bytes([115; 16]))),
                detached: false,
                mode: daemon::RepositoryIndexMode::RepositoryIndexRebuild as i32,
            },
            &context(115),
            &mut no_reply,
        )
        .expect_err("clean rebuild requires an active repository");
        assert_eq!(cold_error.code(), ErrorCode::InvalidArgument);
        let deep = repository_index(
            &lanes,
            resources,
            daemon::RepositoryIndexRequest {
                schema_version: Some(schema_version()),
                root: root.clone(),
                operation: Some(operation_to_wire(deep_operation)),
                detached: false,
                mode: daemon::RepositoryIndexMode::RepositoryIndexDeep as i32,
            },
            &deep_context,
            &mut no_reply,
        )
        .expect("deep generation publishes");
        let deep_generation = parse_generation(deep.published_generation.as_ref())
            .expect("deep generation has a stable identity");
        assert_eq!(
            deep.selected_analysis_mode,
            daemon::RepositoryIndexAnalysisMode::Unspecified as i32
        );
        assert_eq!(calls.load(AtomicOrdering::Relaxed), 1);

        let clean_operation = OperationId::from_bytes([118; 16]);
        let clean_context = context(118);
        let clean = repository_index(
            &lanes,
            resources,
            daemon::RepositoryIndexRequest {
                schema_version: Some(schema_version()),
                root: root.clone(),
                operation: Some(operation_to_wire(clean_operation)),
                detached: false,
                mode: daemon::RepositoryIndexMode::RepositoryIndexRebuild as i32,
            },
            &clean_context,
            &mut no_reply,
        )
        .expect("deep clean rebuild publishes");
        let clean_generation = parse_generation(clean.published_generation.as_ref())
            .expect("clean generation has a stable identity");
        assert_ne!(clean_generation, deep_generation);
        assert_eq!(
            parse_generation(clean.parent_generation.as_ref())
                .expect("clean rebuild retains the active parent"),
            deep_generation
        );
        assert_eq!(
            clean.mode,
            daemon::RepositoryIndexMode::RepositoryIndexRebuild as i32
        );
        assert_eq!(
            clean.selected_analysis_mode,
            daemon::RepositoryIndexAnalysisMode::RepositoryIndexAnalysisDeep as i32
        );
        assert_eq!(calls.load(AtomicOrdering::Relaxed), 2);
        let repository =
            parse_repository(clean.repository.as_ref()).expect("repository identity is valid");
        let service_guard = read_service(&service).expect("service read lock opens");
        let deep_status = service_guard
            .repository_status(repository, Some(deep_generation))
            .expect("deep generation status resolves");
        let clean_status = service_guard
            .repository_status(repository, Some(clean_generation))
            .expect("clean generation status resolves");
        assert_eq!(clean_status.logical_snapshot, deep_status.logical_snapshot);
        drop(service_guard);
        let clean_operation_status = repository_operation_status(
            service.as_ref(),
            &handle,
            &metadata,
            &runtime,
            daemon::RepositoryOperationStatusRequest {
                schema_version: Some(schema_version()),
                operation: Some(operation_to_wire(clean_operation)),
                action: daemon::RepositoryOperationAction::RepositoryOperationGet as i32,
                wait_ms: None,
                after_revision: None,
            },
            &clean_context,
        )
        .expect("clean operation status is available");
        assert_eq!(
            clean_operation_status.build_strategy,
            daemon::RepositoryBuildStrategy::RepositoryBuildCleanRebuild as i32
        );
        assert_eq!(clean_operation_status.reused_files, 0);
        assert_eq!(clean_operation_status.reused_facts, 0);
        let fact_work = clean_operation_status
            .fact_work
            .expect("clean grouped evidence is available");
        assert!(fact_work
            .planned
            .expect("planned groups are available")
            .groups
            .iter()
            .all(|group| {
                group.disposition
                    == daemon::RepositoryFactWorkDisposition::RepositoryFactWorkRebuild as i32
                    && group.cause
                        == daemon::RepositoryFactWorkCause::RepositoryFactWorkUserRequestedCleanRebuild
                            as i32
            }));
        let mut legacy_context = context(119);
        legacy_context.selected_protocol_minor = 15;
        let legacy_status = repository_operation_status(
            service.as_ref(),
            &handle,
            &metadata,
            &runtime,
            daemon::RepositoryOperationStatusRequest {
                schema_version: Some(schema_version()),
                operation: Some(operation_to_wire(clean_operation)),
                action: daemon::RepositoryOperationAction::RepositoryOperationGet as i32,
                wait_ms: None,
                after_revision: None,
            },
            &legacy_context,
        )
        .expect("minor fifteen status remains decodable");
        assert_eq!(
            legacy_status.build_strategy,
            daemon::RepositoryBuildStrategy::Unspecified as i32
        );
        assert!(legacy_status.fact_work.is_none());
        assert!(legacy_status.invalidation_trace_json.is_none());
        assert_eq!(legacy_status.reused_files, 0);
        assert_eq!(legacy_status.rebuilt_files, 0);

        let auto_operation = OperationId::from_bytes([117; 16]);
        let auto_context = context(117);
        let auto = repository_index(
            &lanes,
            resources,
            daemon::RepositoryIndexRequest {
                schema_version: Some(schema_version()),
                root,
                operation: Some(operation_to_wire(auto_operation)),
                detached: false,
                mode: daemon::RepositoryIndexMode::RepositoryIndexAuto as i32,
            },
            &auto_context,
            &mut no_reply,
        )
        .expect("unchanged Auto request retains the deep generation");

        assert_eq!(
            parse_generation(auto.published_generation.as_ref())
                .expect("Auto generation has a stable identity"),
            clean_generation
        );
        assert_eq!(
            auto.mode,
            daemon::RepositoryIndexMode::RepositoryIndexDeep as i32
        );
        assert_eq!(
            auto.selected_analysis_mode,
            daemon::RepositoryIndexAnalysisMode::Unspecified as i32
        );
        assert!(auto.semantic_operation.is_none());
        assert_eq!(calls.load(AtomicOrdering::Relaxed), 2);
        assert!(matches!(
            refinement_receiver.try_recv(),
            Err(mpsc::TryRecvError::Empty)
        ));
        assert!(matches!(
            journal.status(semantic_refinement_operation(auto_operation)),
            Err(OperationError::NotFound)
        ));

        let status = repository_operation_status(
            service.as_ref(),
            &handle,
            &metadata,
            &runtime,
            daemon::RepositoryOperationStatusRequest {
                schema_version: Some(schema_version()),
                operation: Some(operation_to_wire(auto_operation)),
                action: daemon::RepositoryOperationAction::RepositoryOperationGet as i32,
                wait_ms: None,
                after_revision: None,
            },
            &auto_context,
        )
        .expect("retained operation status is available");
        assert_eq!(
            status.build_strategy,
            daemon::RepositoryBuildStrategy::RepositoryBuildRetainedGeneration as i32
        );
        assert_eq!(status.changed_inputs, 0);
        assert_eq!(status.changed_files, 0);
        assert_eq!(status.rebuilt_files, 0);
        assert_eq!(status.rebuilt_facts, 0);
        assert!(status.semantic_operation.is_none());

        drop(handle);
        actor.join().expect("journal actor joins");
    }

    #[test]
    fn auto_index_keeps_the_structural_stage_when_semantic_refinement_fails() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let fixture = durable_test_tempdir();
        fs::create_dir(fixture.path().join("src")).expect("fixture source directory exists");
        fs::write(
            fixture.path().join("src/lib.rs"),
            "pub fn structural_stage() -> bool { true }\n",
        )
        .expect("fixture source writes");

        let calls = Arc::new(AtomicUsize::new(0));
        let analyzer: Arc<dyn FirstSliceProjectAnalyzer> = Arc::new(FailingSemanticAnalyzer {
            calls: Arc::clone(&calls),
            error: FirstSliceProjectAnalysisError::WallTimeLimit,
        });
        let deadline = Instant::now() + Duration::from_secs(30);
        let cancellation = Cancellation::with_deadline(deadline);
        let service = Arc::new(RwLock::new(
            FirstSliceService::new_durable_with_project_analyzer(
                3,
                paths.state_dir(),
                analyzer,
                &cancellation,
            )
            .expect("durable semantic service initializes"),
        ));
        let journal = Arc::new(
            OperationJournal::open(&paths.operation_journal_path())
                .expect("operation journal opens"),
        );
        let actor = JournalActor::start(Arc::clone(&journal), 8, 8).expect("journal actor starts");
        let handle = actor.handle();
        let metadata = Mutex::new(OperationMetadataSet::new(8));
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_time()
            .build()
            .expect("runtime builds");
        let resources = ServiceRequestResources {
            journal: &handle,
            metadata: &metadata,
            runtime: &runtime,
            catalog_epoch: Instant::now(),
            publication_hook: None,
        };
        let context = FirstSliceIpcContext {
            client_instance_id: ClientInstanceId::from_bytes([7; 16]),
            selected_protocol_minor: rootlight_daemon_core::PROTOCOL_MINOR,
            cancellation,
            deadline,
            effective_budget: None,
            index_admission: None,
        };
        let operation = OperationId::from_bytes([91; 16]);
        let request = daemon::RepositoryIndexRequest {
            schema_version: Some(schema_version()),
            root: fixture.path().to_string_lossy().into_owned(),
            operation: Some(operation_to_wire(operation)),
            detached: false,
            mode: daemon::RepositoryIndexMode::RepositoryIndexAuto as i32,
        };
        let (reply_sender, reply_receiver) = tokio::sync::oneshot::channel();
        let mut reply = Some(reply_sender);
        let index_serialization = Arc::new(Mutex::new(()));
        let semantic_refinements = Arc::new(Mutex::new(BTreeMap::new()));
        let (refinement, refinement_receiver) = mpsc::sync_channel(1);
        let lanes = FirstSliceServiceLanes {
            service: Arc::clone(&service),
            index_serialization,
            semantic_refinements,
            graph_projections: Arc::new(Mutex::new(GraphProjectionRegistry::new())),
            refinement,
            recovery_ready: Arc::new(AtomicBool::new(true)),
            recovery_complete: Arc::new(AtomicBool::new(true)),
            recovery_admission_ready: Arc::new(AtomicBool::new(true)),
            recovering_repositories: Arc::new(RwLock::new(BTreeMap::new())),
            recovery_demand: Arc::new(Mutex::new(RecoveryDemandQueue::default())),
            support_state: None,
        };

        let response = repository_index(&lanes, resources, request, &context, &mut reply)
            .expect("structural stage publishes");

        assert!(reply.is_none());
        assert_eq!(
            response.mode,
            daemon::RepositoryIndexMode::RepositoryIndexStructural as i32
        );
        assert!(response.published_generation.is_some());
        assert_eq!(
            parse_operation(response.semantic_operation.as_ref())
                .expect("scheduled semantic child has a stable identity"),
            semantic_refinement_operation(operation)
        );
        let auto_operation_context = journal
            .repository_operation_context(operation)
            .expect("auto operation context persists");
        assert_eq!(auto_operation_context.mode, RepositoryOperationMode::Auto);
        let planning = auto_operation_context
            .planning
            .as_ref()
            .expect("pre-work planning persists before publication");
        assert_eq!(planning.build_strategy, RepositoryBuildStrategy::Initial);
        assert!(planning.estimated_analysis_units > 0);
        assert!(planning.estimated_files > 0);
        assert!(planning.estimated_facts > 0);
        assert!(planning.estimated_cost_units >= planning.estimated_facts);
        assert!(planning.estimated_durable_bytes > 0);
        let delivered = runtime
            .block_on(reply_receiver)
            .expect("structural response is delivered")
            .expect("structural response succeeds");
        assert!(matches!(
            delivered,
            FirstSliceIpcResponse::RepositoryIndex(ref delivered) if delivered == &response
        ));
        assert_eq!(calls.load(AtomicOrdering::Relaxed), 0);
        let repositories = read_service(&service)
            .expect("service read lock is available")
            .list_repositories();
        let [repository] = repositories.as_slice() else {
            panic!("only one repository is active");
        };
        assert_eq!(repository.semantic_freshness, "pending_refinement");
        let catalog = {
            let service = read_service(&service).expect("service read lock is available");
            repository_catalog_page(
                &service,
                catalog_request(20, false, Vec::new(), None, None),
                Instant::now(),
            )
            .expect("catalog remains available during semantic refinement")
        };
        assert_eq!(catalog.repositories.len(), 1);
        assert_eq!(catalog.repositories[0].structural_freshness, "current");
        assert_eq!(catalog.repositories[0].semantic_freshness, "stale");
        let locate = {
            let service = read_service(&service).expect("service read lock is available");
            code_locate(
                &service,
                daemon::CodeLocateRequest {
                    kind_filter: None,
                    schema_version: Some(schema_version()),
                    repository: Some(repository_to_wire(repository.repository)),
                    generation: Some(daemon::GenerationSelector {
                        selector: Some(daemon::generation_selector::Selector::Active(true)),
                    }),
                    query: "structural_stage".to_owned(),
                    mode: daemon::FirstSliceLocateMode::FirstSliceLocateExact as i32,
                    maximum_results: 8,
                    page_offset: 0,
                    languages: vec!["rust".to_owned()],
                    path_prefixes: Vec::new(),
                },
                &context,
            )
            .expect("the structural generation remains queryable")
        };
        let query_context = locate.context.expect("query context exists");
        assert!(!locate.hits.is_empty());
        assert!(locate.hits.iter().all(|hit| hit.language == "rust"));
        assert_eq!(query_context.structural_freshness, "current");
        assert_eq!(query_context.semantic_freshness, "stale");
        let unknown_language = {
            let service = read_service(&service).expect("service read lock is available");
            code_locate(
                &service,
                daemon::CodeLocateRequest {
                    kind_filter: None,
                    schema_version: Some(schema_version()),
                    repository: Some(repository_to_wire(repository.repository)),
                    generation: Some(daemon::GenerationSelector {
                        selector: Some(daemon::generation_selector::Selector::Active(true)),
                    }),
                    query: "structural_stage".to_owned(),
                    mode: daemon::FirstSliceLocateMode::FirstSliceLocateExact as i32,
                    maximum_results: 8,
                    page_offset: 0,
                    languages: vec!["unknown".to_owned()],
                    path_prefixes: Vec::new(),
                },
                &context,
            )
            .expect("an unknown canonical language selects an empty query domain")
        };
        assert!(unknown_language.hits.is_empty());
        assert_eq!(unknown_language.matched_candidates, 0);
        assert_eq!(
            unknown_language
                .context
                .expect("query context exists")
                .coverage_status,
            daemon::FirstSliceCoverageStatus::FirstSliceCoverageComplete as i32
        );
        let refinement = refinement_receiver
            .recv_timeout(Duration::from_secs(1))
            .expect("semantic refinement is scheduled");
        let mut refinement_reply = None;
        drop(repository_index_with_intent(
            &lanes,
            resources,
            refinement.request,
            &refinement.context,
            &mut refinement_reply,
            RepositoryIndexIntent::SemanticRefinement {
                structural_generation: refinement.structural_generation,
            },
            None,
        ));
        assert_eq!(calls.load(AtomicOrdering::Relaxed), 1);
        assert_eq!(
            journal
                .status(operation)
                .expect("structural operation remains queryable")
                .state,
            OperationState::Succeeded
        );
        let semantic_operation = semantic_refinement_operation(operation);
        let semantic_record = journal
            .status(semantic_operation)
            .expect("semantic operation remains queryable");
        assert_eq!(semantic_record.state, OperationState::Failed);
        let semantic_error = semantic_record.error.as_ref().expect("failure is recorded");
        assert_eq!(semantic_error.code(), ErrorCode::ResourceExhausted);
        assert_eq!(
            semantic_error.details().get(&static_detail_key("resource")),
            Some(&PublicValue::Label(static_safe_label(
                "adapter_wall_time_ms"
            )))
        );
        assert_eq!(
            semantic_error
                .details()
                .get(&static_detail_key("structural_fallback")),
            Some(&PublicValue::Boolean(true))
        );
        assert!(!semantic_error.retryable());
        assert_eq!(semantic_error.retry_after_ms(), None);
        assert!(!semantic_error.next_actions().contains(&NextAction::Retry));
        assert!(semantic_record.progress.completed > 0);
        assert_eq!(semantic_record.progress.total, 6);
        let semantic_context = journal
            .repository_operation_context(semantic_operation)
            .expect("semantic operation observations remain queryable");
        assert!(semantic_context.files_examined > 0);
        assert!(semantic_context.bytes_examined > 0);
        assert_eq!(
            metadata
                .lock()
                .expect("operation metadata locks")
                .records
                .get(&semantic_operation)
                .expect("semantic metadata remains queryable")
                .started_unix_ms,
            semantic_context.started_unix_ms
        );
        let status = repository_operation_status(
            service.as_ref(),
            &handle,
            &metadata,
            &runtime,
            daemon::RepositoryOperationStatusRequest {
                schema_version: Some(schema_version()),
                operation: Some(operation_to_wire(operation)),
                action: daemon::RepositoryOperationAction::RepositoryOperationGet as i32,
                wait_ms: None,
                after_revision: None,
            },
            &context,
        )
        .expect("parent status is available");
        assert_eq!(
            parse_operation(status.semantic_operation.as_ref())
                .expect("durably admitted semantic child is exposed"),
            semantic_refinement_operation(operation)
        );
        assert_eq!(
            status.build_strategy,
            daemon::RepositoryBuildStrategy::RepositoryBuildInitial as i32
        );
        assert!(status.planning.is_some());
        assert!(status.rebuilt_files > 0);
        assert!(status.rebuilt_facts > 0);
        assert_eq!(status.newly_written_bytes, status.written_bytes);
        let trace: serde_json::Value = serde_json::from_slice(
            status
                .invalidation_trace_json
                .as_deref()
                .expect("bounded invalidation trace is exposed"),
        )
        .expect("invalidation trace is canonical JSON");
        assert_eq!(trace["version"], "1.0");
        let visible_entries = trace["entries"]
            .as_array()
            .expect("trace entries are an array")
            .len();
        let total_entries = trace["total_entries"]
            .as_u64()
            .expect("trace total is numeric");
        assert!(total_entries >= u64::try_from(visible_entries).expect("entry count fits"));
        assert_eq!(
            trace["complete"],
            total_entries == u64::try_from(visible_entries).expect("entry count fits")
        );
        assert!(status.reserved_memory_bytes > 0);
        assert!(status.owned_memory_bytes > 0);
        assert!(status.owned_memory_bytes <= status.reserved_memory_bytes);

        drop(handle);
        actor.join().expect("journal actor joins");
        drop(journal);
        let reopened = OperationJournal::open(&paths.operation_journal_path())
            .expect("operation journal reopens");
        let recovered = reopened
            .status(semantic_operation)
            .expect("semantic progress survives restart");
        assert_eq!(recovered.progress, semantic_record.progress);
        let recovered_context = reopened
            .repository_operation_context(semantic_operation)
            .expect("semantic resource observations survive restart");
        assert_eq!(
            (
                recovered_context.files_examined,
                recovered_context.bytes_examined
            ),
            (
                semantic_context.files_examined,
                semantic_context.bytes_examined
            )
        );
    }

    #[test]
    fn full_refinement_queue_terminalizes_the_durable_semantic_child() {
        let repository = RepositoryId::from_bytes([31; 16]);
        let generation = GenerationId::from_bytes([32; 20]);
        let operation = OperationId::from_bytes([33; 16]);
        let deadline = Instant::now() + Duration::from_secs(5);
        let context = FirstSliceIpcContext {
            client_instance_id: ClientInstanceId::from_bytes([34; 16]),
            selected_protocol_minor: rootlight_daemon_core::PROTOCOL_MINOR,
            cancellation: Cancellation::with_deadline(deadline),
            deadline,
            effective_budget: None,
            index_admission: None,
        };
        let (refinement, receiver) = mpsc::sync_channel(1);
        let (occupied_admitted, _occupied_admission) = mpsc::sync_channel(1);
        refinement
            .try_send(SemanticRefinementCommand {
                request: daemon::RepositoryIndexRequest::default(),
                context: context.clone(),
                operation: OperationId::from_bytes([35; 16]),
                repository,
                structural_generation: generation,
                admitted: occupied_admitted,
            })
            .expect("refinement queue is occupied");
        let response = daemon::RepositoryIndexResponse {
            repository: Some(repository_to_wire(repository)),
            operation: Some(operation_to_wire(operation)),
            state: daemon::OperationState::Succeeded as i32,
            published_generation: Some(generation_to_wire(generation)),
            mode: daemon::RepositoryIndexMode::RepositoryIndexStructural as i32,
            ..daemon::RepositoryIndexResponse::default()
        };
        let semantic_refinements = Arc::new(Mutex::new(BTreeMap::new()));
        let mut reply = None;
        let journal = Arc::new(OperationJournal::open_in_memory().expect("journal opens"));
        journal
            .submit(
                OperationSubmission::new(
                    operation,
                    OperationKind::RepositoryIndex,
                    PlanHash::from_bytes([33; 32]),
                    context.client_instance_id,
                    true,
                    None,
                    None,
                )
                .expect("parent submission is valid")
                .with_repository_context(
                    RepositoryOperationSubmission::new(
                        repository,
                        None,
                        1,
                        1,
                        RepositoryOperationMode::Auto,
                    )
                    .expect("parent repository context is valid")
                    .with_root_identity([36; 32]),
                )
                .expect("repository context matches the operation kind"),
            )
            .expect("parent operation submits");
        let actor = JournalActor::start(Arc::clone(&journal), 4, 4).expect("journal actor starts");
        let handle = actor.handle();
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_time()
            .build()
            .expect("runtime builds");

        let completed = complete_auto_structural_index(
            "repository",
            operation,
            &context,
            &mut reply,
            response.clone(),
            AutoRefinementResources {
                intent: RepositoryIndexIntent::Requested,
                semantic_refinements: &semantic_refinements,
                refinement: &refinement,
                journal: &handle,
                runtime: &runtime,
            },
        )
        .expect("queue pressure cannot replace structural success");

        assert_eq!(
            completed.published_generation,
            response.published_generation
        );
        let semantic_operation = parse_operation(completed.semantic_operation.as_ref())
            .expect("the durable semantic child is advertised");
        assert_eq!(semantic_operation, semantic_refinement_operation(operation));
        let semantic_record = journal
            .status(semantic_operation)
            .expect("the rejected semantic child remains queryable");
        assert_eq!(semantic_record.state, OperationState::Failed);
        assert_eq!(
            semantic_record
                .error
                .as_ref()
                .expect("queue rejection is persisted")
                .code(),
            ErrorCode::ResourceExhausted
        );
        let semantic_context = journal
            .repository_operation_context(semantic_operation)
            .expect("semantic repository context is durable");
        let deadline_unix_ms = semantic_record
            .deadline_unix_ms
            .expect("detached semantic refinement has a deadline");
        let admitted_timeout_ms = deadline_unix_ms
            .checked_sub(semantic_context.started_unix_ms)
            .expect("semantic deadline follows admission");
        let configured_timeout_ms = u64::try_from(DETACHED_SEMANTIC_REFINEMENT_TIMEOUT.as_millis())
            .expect("semantic timeout fits");
        assert!(
            (configured_timeout_ms.saturating_sub(5_000)..=configured_timeout_ms)
                .contains(&admitted_timeout_ms),
            "semantic refinement retains the reviewed two-hour deadline"
        );
        assert!(
            semantic_refinements
                .lock()
                .expect("refinement metadata locks")
                .is_empty()
        );
        drop(receiver);
        drop(handle);
        actor.join().expect("journal actor joins");
    }

    #[test]
    fn semantic_refinement_preserves_its_admitted_work_deadline() {
        let now = Instant::now();
        let admitted_deadline = now + DETACHED_SEMANTIC_REFINEMENT_TIMEOUT;
        let structural_generation = GenerationId::from_bytes([37; 20]);

        assert_eq!(
            repository_index_work_deadline(
                RepositoryIndexIntent::SemanticRefinement {
                    structural_generation,
                },
                true,
                admitted_deadline,
                now,
            )
            .expect("semantic deadline is valid"),
            admitted_deadline
        );
        assert_eq!(
            repository_index_work_deadline(
                RepositoryIndexIntent::Requested,
                true,
                admitted_deadline,
                now,
            )
            .expect("detached index deadline is valid"),
            now + DETACHED_INDEX_TIMEOUT
        );
    }

