    #[test]
    fn operation_metadata_reuses_capacity_only_after_terminalization() {
        let first = OperationId::from_bytes([60; 16]);
        let second = OperationId::from_bytes([61; 16]);
        let mut metadata = OperationMetadataSet::new(1);
        metadata
            .reserve(first, 1, None)
            .expect("first metadata reserves");
        assert_eq!(
            metadata
                .reserve(second, 2, None)
                .expect_err("nonterminal metadata is retained")
                .code(),
            ErrorCode::ResourceExhausted
        );

        metadata.mark_terminal(first);
        metadata
            .reserve(second, 2, None)
            .expect("terminal metadata is evicted");
        assert!(!metadata.records.contains_key(&first));
        assert!(metadata.records.contains_key(&second));
    }

    #[test]
    fn committed_restore_accepts_a_reused_generation_lineage() {
        let operation = OperationId::from_bytes([62; 16]);
        let repository = RepositoryId::from_bytes([63; 16]);
        let generation = GenerationId::from_bytes([64; 20]);
        let lineage_parent = GenerationId::from_bytes([65; 20]);
        let started_unix_ms = 1_700_000_000_066;
        let journal = OperationJournal::open_in_memory().expect("journal opens");
        let submission = repository_submission(operation, 62)
            .with_repository_context(
                RepositoryOperationSubmission::new(
                    repository,
                    Some(generation),
                    started_unix_ms,
                    64 * 1024 * 1024,
                    RepositoryOperationMode::Deep,
                )
                .expect("repository context is valid")
                .with_root_identity([67; 32]),
            )
            .expect("repository context attaches");
        journal.submit(submission).expect("operation submits");
        journal
            .start_execution(operation)
            .expect("operation starts");
        journal
            .complete_repository_publication(operation)
            .expect("operation succeeds");
        let context = journal
            .record_repository_publication(operation, generation)
            .expect("published generation projects durably");
        let mut unrelated_parent_context = context.clone();
        unrelated_parent_context.parent_generation = Some(GenerationId::from_bytes([66; 20]));
        let record = journal
            .status(operation)
            .expect("operation remains visible");
        let receipt = FirstSliceIndexReceipt {
            repository,
            generation,
            parent: Some(lineage_parent),
            discovered_inputs: 3,
            visited_entries: 4,
            discovery_complete: true,
            excluded_inputs: 1,
            oversized_inputs: 0,
            binary_inputs: 0,
            policy_excluded_inputs: 1,
            indexed_files: 3,
            entities: 6,
            lexical_documents: 3,
            oracle_allocated_bytes: 4_096,
            estimated_disk_bytes: 64 * 1024 * 1024,
            retained_durable_bytes: 0,
            logical_snapshot: None,
            diagnostics: Vec::new(),
            elapsed_micros: 10,
        };
        let publication = FirstSliceDurableOperation {
            operation,
            started_unix_ms,
            provider: FirstSliceIndexProvider::Unknown,
            receipt,
        };
        let mut metadata = OperationMetadataSet::new(1);
        metadata
            .restore_context(context, &record)
            .expect("durable context restores");

        metadata
            .restore_committed(publication.clone(), &record)
            .expect("the exact reused generation restores");
        let restored = metadata
            .records
            .get(&operation)
            .expect("restored metadata remains visible");
        assert_eq!(restored.parent_generation, Some(generation));
        assert_eq!(restored.published_generation, Some(generation));
        assert_eq!(restored.receipt.as_ref(), Some(&publication.receipt));

        let mut unrelated_parent = OperationMetadataSet::new(1);
        unrelated_parent
            .restore_context(unrelated_parent_context, &record)
            .expect("durable context with an unrelated parent restores");
        assert_eq!(
            unrelated_parent
                .restore_committed(publication, &record)
                .expect_err("an unrelated parent cannot reuse the lineage exception"),
            FirstSliceError::Retention
        );
    }

    #[test]
    fn startup_context_restore_bounds_terminal_metadata_without_failure() {
        fn retained_operation(index: u16) -> OperationId {
            let mut bytes = [0_u8; 16];
            bytes[..2].copy_from_slice(&index.to_be_bytes());
            OperationId::from_bytes(bytes)
        }

        let journal = OperationJournal::open_in_memory().expect("journal opens");
        let repository = RepositoryId::from_bytes([62; 16]);
        for index in 1_u16..=257 {
            let operation = retained_operation(index);
            let submission = repository_submission(operation, 62)
                .with_repository_context(
                    RepositoryOperationSubmission::new(
                        repository,
                        None,
                        1_700_000_000_000 + u64::from(index),
                        64 * 1024 * 1024,
                        RepositoryOperationMode::Structural,
                    )
                    .expect("repository context is valid")
                    .with_root_identity([63; 32]),
                )
                .expect("repository context attaches");
            journal.submit(submission).expect("operation submits");
            journal
                .interrupt_deadline(operation)
                .expect("operation becomes terminal");
        }

        let mut metadata = OperationMetadataSet::new(DEFAULT_OPERATION_METADATA);
        for context in journal
            .repository_operation_contexts()
            .expect("startup contexts load")
        {
            let record = journal
                .status(context.operation)
                .expect("startup operation status loads");
            metadata
                .restore_context(context, &record)
                .expect("bounded startup restore cannot fail on terminal history");
        }

        assert_eq!(metadata.records.len(), DEFAULT_OPERATION_METADATA);
        assert!(metadata.records.contains_key(&retained_operation(257)));
        assert!(!metadata.records.contains_key(&retained_operation(1)));
    }

    #[test]
    fn recovery_demand_preserves_unique_arrival_order() {
        let first = RepositoryId::from_bytes([2; 16]);
        let second = RepositoryId::from_bytes([1; 16]);
        let mut demand = RecoveryDemandQueue::default();

        demand.insert(first);
        demand.insert(second);
        demand.insert(first);

        assert_eq!(
            demand.repositories.iter().copied().collect::<Vec<_>>(),
            [first, second]
        );
        assert!(demand.contains(&first));
        demand.remove(&first);
        assert_eq!(
            demand.repositories.iter().copied().collect::<Vec<_>>(),
            [second]
        );
    }

    #[test]
    fn initial_recovery_demand_grace_is_bounded_and_skips_single_repository() {
        let (refinement, _refinement_receiver) = mpsc::sync_channel(1);
        let lanes = FirstSliceServiceLanes {
            service: Arc::new(RwLock::new(
                FirstSliceService::new(1).expect("empty service initializes"),
            )),
            index_serialization: Arc::new(Mutex::new(())),
            semantic_refinements: Arc::new(Mutex::new(BTreeMap::new())),
            graph_projections: Arc::new(Mutex::new(GraphProjectionRegistry::new())),
            refinement,
            recovery_ready: Arc::new(AtomicBool::new(false)),
            recovery_complete: Arc::new(AtomicBool::new(false)),
            recovery_admission_ready: Arc::new(AtomicBool::new(true)),
            recovering_repositories: Arc::new(RwLock::new(BTreeMap::new())),
            recovery_demand: Arc::new(Mutex::new(RecoveryDemandQueue::default())),
            support_state: None,
        };
        let stopping = AtomicBool::new(false);
        let cancellation = Cancellation::new();

        let single_started = Instant::now();
        wait_for_initial_recovery_demand(
            &lanes,
            1,
            &stopping,
            &cancellation,
            Duration::from_secs(5),
        )
        .expect("single-repository recovery starts immediately");
        assert!(single_started.elapsed() < Duration::from_secs(1));

        let multiple_started = Instant::now();
        wait_for_initial_recovery_demand(
            &lanes,
            2,
            &stopping,
            &cancellation,
            Duration::from_millis(50),
        )
        .expect("multi-repository demand grace expires cleanly");
        assert!(multiple_started.elapsed() >= Duration::from_millis(40));
        assert!(multiple_started.elapsed() < Duration::from_secs(1));

        let demand = Arc::clone(&lanes.recovery_demand);
        let requested = RepositoryId::from_bytes([17; 16]);
        let requester = thread::spawn(move || {
            thread::sleep(Duration::from_millis(50));
            demand
                .lock()
                .expect("recovery demand writes")
                .insert(requested);
        });
        let demand_started = Instant::now();
        wait_for_initial_recovery_demand(
            &lanes,
            2,
            &stopping,
            &cancellation,
            Duration::from_secs(5),
        )
        .expect("first interactive demand ends the grace");
        requester.join().expect("demand requester joins");
        assert!(demand_started.elapsed() >= Duration::from_millis(40));
        assert!(demand_started.elapsed() < Duration::from_secs(1));
    }

    #[test]
    fn deferred_recovery_keeps_catalog_reads_and_lifecycle_failures_bounded() {
        let fixture = TempDir::new().expect("fixture root exists");
        fs::create_dir(fixture.path().join("src")).expect("source directory exists");
        fs::write(
            fixture.path().join("src/lib.rs"),
            "pub fn available_during_recovery() -> bool { true }\n",
        )
        .expect("source writes");
        let cancellation = Cancellation::with_deadline(Instant::now() + Duration::from_secs(30));
        let mut service =
            FirstSliceService::new(DEFAULT_GENERATION_RETENTION).expect("service initializes");
        let receipt = service
            .index_rust_fixture(fixture.path(), &cancellation)
            .expect("active generation publishes");
        let service = Arc::new(RwLock::new(service));
        let journal = Arc::new(OperationJournal::open_in_memory().expect("journal opens"));
        let actor = JournalActor::start(Arc::clone(&journal), 4, 4).expect("actor starts");
        let handle = actor.handle();
        let metadata = Mutex::new(OperationMetadataSet::new(4));
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_time()
            .build()
            .expect("runtime builds");
        let (_refinement, refinement_receiver) = mpsc::sync_channel(1);
        let recovery_ready = Arc::new(AtomicBool::new(false));
        let lanes = FirstSliceServiceLanes {
            service,
            index_serialization: Arc::new(Mutex::new(())),
            semantic_refinements: Arc::new(Mutex::new(BTreeMap::new())),
            graph_projections: Arc::new(Mutex::new(GraphProjectionRegistry::new())),
            refinement: _refinement,
            recovery_ready: Arc::clone(&recovery_ready),
            recovery_complete: Arc::new(AtomicBool::new(false)),
            recovery_admission_ready: Arc::new(AtomicBool::new(false)),
            recovering_repositories: Arc::new(RwLock::new(BTreeMap::new())),
            recovery_demand: Arc::new(Mutex::new(RecoveryDemandQueue::default())),
            support_state: None,
        };
        let resources = ServiceRequestResources {
            journal: &handle,
            metadata: &metadata,
            runtime: &runtime,
            catalog_epoch: Instant::now(),
            publication_hook: None,
        };
        let context = || {
            let deadline = Instant::now() + Duration::from_secs(5);
            FirstSliceIpcContext {
                client_instance_id: ClientInstanceId::from_bytes([93; 16]),
                selected_protocol_minor: rootlight_daemon_core::PROTOCOL_MINOR,
                cancellation: Cancellation::with_deadline(deadline),
                deadline,
                effective_budget: None,
                index_admission: None,
            }
        };
        let mut reply = None;

        let listed = execute_service_request(
            &lanes,
            resources,
            FirstSliceIpcRequest::RepositoryList(daemon::RepositoryListRequest {
                max_results: Some(20),
                query: None,
            }),
            context(),
            &mut reply,
        )
        .expect("catalog remains readable while recovery runs");
        assert!(matches!(
            listed,
            FirstSliceIpcResponse::RepositoryList(ref response)
                if response.repositories.len() == 1
        ));

        let recovery_operation = OperationId::from_bytes([92; 16]);
        let recovery_context = RepositoryOperationSubmission::new(
            receipt.repository,
            Some(receipt.generation),
            1,
            0,
            RepositoryOperationMode::Structural,
        )
        .expect("recovery context is valid");
        journal
            .submit(
                OperationSubmission::new(
                    recovery_operation,
                    OperationKind::Recovery,
                    PlanHash::from_bytes([92; 32]),
                    ClientInstanceId::SYSTEM,
                    true,
                    None,
                    None,
                )
                .expect("recovery submission is valid")
                .with_repository_context(recovery_context)
                .expect("recovery is repository bound"),
            )
            .expect("recovery operation persists");
        journal
            .start_execution(recovery_operation)
            .expect("recovery starts");
        {
            let mut recovering = lanes
                .recovering_repositories
                .write()
                .expect("recovery map writes");
            recovering.insert(
                RepositoryId::from_bytes([0; 16]),
                RepositoryRecoveryState {
                    generation: GenerationId::from_bytes([1; 20]),
                    operation: None,
                    phase: RepositoryRecoveryPhase::ActiveGeneration,
                    current: false,
                },
            );
            recovering.insert(
                receipt.repository,
                RepositoryRecoveryState {
                    generation: receipt.generation,
                    operation: Some(recovery_operation),
                    phase: RepositoryRecoveryPhase::ActiveGeneration,
                    current: true,
                },
            );
        }
        let service_write = lanes
            .service
            .write()
            .expect("service write lock remains healthy");
        let bounded_operation = OperationId::from_bytes([96; 16]);
        let bounded_request =
            FirstSliceIpcRequest::RepositoryIndex(daemon::RepositoryIndexRequest {
                schema_version: Some(schema_version()),
                root: fixture.path().display().to_string(),
                operation: Some(operation_to_wire(bounded_operation)),
                detached: true,
                mode: daemon::RepositoryIndexMode::RepositoryIndexStructural as i32,
            });
        let bounded_context = context();
        let (bounded, bounded_receiver) = mpsc::sync_channel(1);
        thread::scope(|scope| {
            let worker = scope.spawn(|| {
                let mut reply = None;
                let resources = ServiceRequestResources {
                    journal: &handle,
                    metadata: &metadata,
                    runtime: &runtime,
                    catalog_epoch: Instant::now(),
                    publication_hook: None,
                };
                let result = execute_service_request(
                    &lanes,
                    resources,
                    bounded_request,
                    bounded_context,
                    &mut reply,
                );
                bounded
                    .send(result)
                    .expect("bounded recovery observation sends");
            });
            let observation = bounded_receiver.recv_timeout(Duration::from_secs(1));
            drop(service_write);
            worker.join().expect("bounded recovery worker joins");
            let error = observation
                .expect("recovery rejection does not wait for the service write lock")
                .expect_err("the exact unrecovered repository remains blocked");
            assert_eq!(error.code(), ErrorCode::Busy);
            assert_eq!(error.repository(), Some(receipt.repository));
            assert_eq!(error.generation(), Some(receipt.generation));
            assert_eq!(error.operation(), Some(recovery_operation));
            assert!(error.retryable());
        });
        let error = execute_service_request(
            &lanes,
            resources,
            FirstSliceIpcRequest::RepositoryCatalogMutation(
                daemon::RepositoryCatalogMutationRequest {
                    repository: Some(repository_to_wire(receipt.repository)),
                    mutation: Some(
                        daemon::repository_catalog_mutation_request::Mutation::Alias(
                            "blocked".to_owned(),
                        ),
                    ),
                },
            ),
            context(),
            &mut reply,
        )
        .expect_err("destructive catalog mutations wait for durable recovery");
        assert_eq!(error.code(), ErrorCode::Busy);
        assert!(error.retryable());
        assert_eq!(
            error.retry_after_ms(),
            Some(u64::from(RECOVERY_RETRY_ACTIVE_MS))
        );
        assert_eq!(
            error.details().get(&static_detail_key("recovery_stage")),
            Some(&PublicValue::Label(static_safe_label("active_generation")))
        );
        assert_eq!(
            error
                .details()
                .get(&static_detail_key("progress_completed")),
            Some(&PublicValue::Unsigned(0))
        );
        assert_eq!(
            error.details().get(&static_detail_key("progress_total")),
            Some(&PublicValue::Unsigned(2))
        );
        assert_eq!(error.repository(), Some(receipt.repository));
        assert_eq!(error.generation(), Some(receipt.generation));
        assert_eq!(error.operation(), Some(recovery_operation));
        assert_eq!(
            error.next_actions(),
            &[NextAction::Retry, NextAction::InspectOperation]
        );

        let requested_index = |operation: OperationId, detached: bool| {
            FirstSliceIpcRequest::RepositoryIndex(daemon::RepositoryIndexRequest {
                schema_version: Some(schema_version()),
                root: fixture.path().display().to_string(),
                operation: Some(operation_to_wire(operation)),
                detached,
                mode: daemon::RepositoryIndexMode::RepositoryIndexStructural as i32,
            })
        };
        let attached_operation = OperationId::from_bytes([93; 16]);
        let index_error = execute_service_request(
            &lanes,
            resources,
            requested_index(attached_operation, false),
            context(),
            &mut reply,
        )
        .expect_err("the exact unrecovered repository remains blocked");
        assert_eq!(index_error.code(), ErrorCode::Busy);
        assert_eq!(index_error.repository(), Some(receipt.repository));
        let detached_operation = OperationId::from_bytes([95; 16]);
        let detached_error = execute_service_request(
            &lanes,
            resources,
            requested_index(detached_operation, true),
            context(),
            &mut reply,
        )
        .expect_err("detached recovery rejection precedes durable admission");
        assert_eq!(detached_error.code(), ErrorCode::Busy);
        assert!(matches!(
            journal.status(attached_operation),
            Err(OperationError::NotFound)
        ));
        assert!(matches!(
            journal.status(detached_operation),
            Err(OperationError::NotFound)
        ));
        assert!(
            lanes
                .recovery_demand
                .lock()
                .expect("recovery demand reads")
                .contains(&receipt.repository)
        );

        let active_error = execute_service_request(
            &lanes,
            resources,
            FirstSliceIpcRequest::RepositoryStatus(status_request(
                receipt.repository,
                Some(receipt.generation),
            )),
            context(),
            &mut reply,
        )
        .expect_err("active generation remains fail-closed until it is installed");
        assert_eq!(active_error.code(), ErrorCode::Busy);
        assert_eq!(active_error.repository(), Some(receipt.repository));
        assert_eq!(active_error.generation(), Some(receipt.generation));

        mark_active_recovery_available(&lanes, receipt.repository)
            .expect("active generation becomes available");
        journal
            .update_progress(recovery_operation, Progress::new(1, 2).unwrap())
            .expect("active recovery phase is durable");
        let retained_error = execute_service_request(
            &lanes,
            resources,
            requested_index(attached_operation, false),
            context(),
            &mut reply,
        )
        .expect_err("same-repository publication waits for retained restore");
        assert_eq!(retained_error.code(), ErrorCode::Busy);
        assert_eq!(
            retained_error.retry_after_ms(),
            Some(u64::from(RECOVERY_RETRY_RETAINED_MS))
        );
        assert_eq!(
            retained_error
                .details()
                .get(&static_detail_key("recovery_stage")),
            Some(&PublicValue::Label(static_safe_label("retained_history")))
        );

        let independent = TempDir::new().expect("independent fixture root exists");
        fs::create_dir(independent.path().join("src")).expect("source directory exists");
        fs::write(
            independent.path().join("src/lib.rs"),
            "pub fn admitted_during_recovery() -> bool { true }\n",
        )
        .expect("source writes");
        let independent_request = || {
            FirstSliceIpcRequest::RepositoryIndex(daemon::RepositoryIndexRequest {
                schema_version: Some(schema_version()),
                root: independent.path().display().to_string(),
                operation: Some(operation_to_wire(OperationId::from_bytes([94; 16]))),
                detached: false,
                mode: daemon::RepositoryIndexMode::RepositoryIndexStructural as i32,
            })
        };
        let bootstrap_error = execute_service_request(
            &lanes,
            resources,
            independent_request(),
            context(),
            &mut reply,
        )
        .expect_err("new publication waits until recovery operations are published");
        assert_eq!(bootstrap_error.code(), ErrorCode::Busy);
        assert_eq!(bootstrap_error.repository(), Some(receipt.repository));
        lanes
            .recovery_admission_ready
            .store(true, Ordering::Release);
        let indexed = execute_service_request(
            &lanes,
            resources,
            independent_request(),
            context(),
            &mut reply,
        )
        .expect("an independent repository publishes during recovery");
        assert!(matches!(
            indexed,
            FirstSliceIpcResponse::RepositoryIndex(ref response)
                if response.repository.as_ref().is_some_and(|repository| {
                    parse_repository(Some(repository)).expect("repository identity is valid")
                        != receipt.repository
                })
        ));

        let status = execute_service_request(
            &lanes,
            resources,
            FirstSliceIpcRequest::RepositoryStatus(status_request(
                receipt.repository,
                Some(receipt.generation),
            )),
            context(),
            &mut reply,
        )
        .expect("exact last-good generation is queryable during retained recovery");
        let FirstSliceIpcResponse::RepositoryStatus(status) = status else {
            panic!("repository status response expected");
        };
        assert_eq!(
            parse_generation(status.resolved_generation.as_ref())
                .expect("resolved generation is valid"),
            receipt.generation
        );
        assert!(!recovery_ready.load(Ordering::Acquire));

        drop(refinement_receiver);
        actor.join().expect("journal actor joins");
    }

    #[test]
    fn failed_first_index_releases_only_its_new_registration() {
        let fixture = TempDir::new().expect("fixture root exists");
        fs::create_dir(fixture.path().join("src")).expect("source directory exists");
        fs::write(
            fixture.path().join("src/lib.rs"),
            "pub fn failed_registration() -> bool { true }\n",
        )
        .expect("source writes");
        let cancellation = Cancellation::with_deadline(Instant::now() + Duration::from_secs(30));
        let mut service =
            FirstSliceService::new(DEFAULT_GENERATION_RETENTION).expect("service initializes");
        let admission = service
            .admit_rust_fixture(fixture.path(), &cancellation)
            .expect("first index reserves the repository");
        assert!(admission.created_repository_reservation());

        settle_unpublished_index_admission(&service, admission)
            .expect("failed first index releases admission");

        let retry = service
            .admit_rust_fixture(fixture.path(), &cancellation)
            .expect("retry reserves the repository again");
        assert!(retry.created_repository_reservation());
        service.release_index_admission(retry);

        service
            .index_rust_fixture(fixture.path(), &cancellation)
            .expect("repository publishes");
        let existing = service
            .admit_rust_fixture(fixture.path(), &cancellation)
            .expect("existing repository admits");
        assert!(!existing.created_repository_reservation());
        settle_unpublished_index_admission(&service, existing)
            .expect("failed refresh preserves the registration");
        let retry = service
            .admit_rust_fixture(fixture.path(), &cancellation)
            .expect("existing repository remains registered");
        assert!(!retry.created_repository_reservation());
    }

    #[test]
    fn startup_does_not_restore_terminal_unpublished_registration() {
        let operation = OperationId::from_bytes([94; 16]);
        let repository = RepositoryId::from_bytes([94; 16]);
        let root_identity = ContentHash::from_bytes([94; 32]);
        let context = RepositoryOperationSubmission::new(
            repository,
            None,
            1,
            0,
            RepositoryOperationMode::Structural,
        )
        .expect("repository context is valid")
        .with_root_identity(*root_identity.as_bytes());
        let submission = OperationSubmission::new(
            operation,
            OperationKind::RepositoryIndex,
            PlanHash::from_bytes([94; 32]),
            ClientInstanceId::from_bytes([94; 16]),
            true,
            None,
            None,
        )
        .and_then(|submission| submission.with_repository_context(context))
        .expect("operation submission is valid");
        let journal = Arc::new(OperationJournal::open_in_memory().expect("journal opens"));
        journal.submit(submission).expect("operation submits");
        journal
            .start_execution(operation)
            .expect("operation starts");
        let actor = JournalActor::start(Arc::clone(&journal), 4, 4).expect("journal actor starts");
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_time()
            .build()
            .expect("runtime builds");
        let failure = internal_error();
        runtime
            .block_on(actor.handle().fail_operation(operation, failure))
            .expect("operation fails");
        let durable_context = journal
            .repository_operation_context(operation)
            .expect("operation context loads");
        let failed = journal.status(operation).expect("failed operation loads");

        assert_eq!(
            startup_registration_identity(&durable_context, &failed),
            None
        );
        for state in [
            OperationState::Interrupted,
            OperationState::Cancelled,
            OperationState::Succeeded,
        ] {
            let mut terminal = failed.clone();
            terminal.state = state;
            assert_eq!(
                startup_registration_identity(&durable_context, &terminal),
                None
            );
        }
        let mut published_context = durable_context;
        published_context.published_generation = Some(GenerationId::from_bytes([94; 20]));
        assert_eq!(
            startup_registration_identity(&published_context, &failed),
            Some(root_identity)
        );
        actor.join().expect("journal actor joins");
    }

    #[test]
    fn active_recovery_is_durable_and_guarded_before_restore_work_starts() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let fixture = durable_test_tempdir();
        fs::create_dir(fixture.path().join("src")).expect("source directory exists");
        fs::write(
            fixture.path().join("src/lib.rs"),
            "pub fn recovery_visibility() -> bool { true }\n",
        )
        .expect("source writes");
        let cancellation = Cancellation::with_deadline(Instant::now() + Duration::from_secs(30));
        let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
            .expect("durable service initializes");
        service
            .index_rust_fixture(fixture.path(), &cancellation)
            .expect("active generation publishes");
        drop(service);
        let (_, deferred) = FirstSliceService::open_durable_deferred(2, paths.state_dir())
            .expect("deferred recovery opens");
        let targets = deferred
            .active_targets()
            .expect("active recovery targets load");
        let [target] = targets.as_slice() else {
            panic!("one active recovery target expected");
        };
        let target = *target;
        let journal = Arc::new(OperationJournal::open_in_memory().expect("journal opens"));
        let actor = JournalActor::start(Arc::clone(&journal), 4, 4).expect("journal actor starts");
        let handle = actor.handle();
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_time()
            .build()
            .expect("runtime builds");
        let recovery = RecoveryOperationGuard::start(&handle, &runtime, target, &cancellation)
            .expect("recovery operation starts");
        let operation = recovery.operation();

        let record = journal
            .status(operation)
            .expect("recovery operation is immediately queryable");
        assert_eq!(record.kind, OperationKind::Recovery);
        assert_eq!(record.state, OperationState::Running);
        let busy = recovery_in_progress(
            Some(target.repository()),
            Some(RepositoryRecoveryState {
                generation: target.generation(),
                operation: Some(operation),
                phase: RepositoryRecoveryPhase::ActiveGeneration,
                current: true,
            }),
            RepositoryRecoveryPhase::ActiveGeneration,
        );
        assert_eq!(busy.operation(), Some(operation));
        assert_eq!(busy.repository(), Some(target.repository()));
        assert_eq!(busy.generation(), Some(target.generation()));
        assert_eq!(
            busy.retry_after_ms(),
            Some(u64::from(RECOVERY_RETRY_ACTIVE_MS))
        );
        assert_eq!(
            busy.next_actions(),
            &[NextAction::Retry, NextAction::InspectOperation]
        );
        let context = journal
            .repository_operation_context(operation)
            .expect("recovery repository context persists");
        assert_eq!(context.repository, target.repository());
        assert_eq!(context.parent_generation, Some(target.generation()));
        assert_eq!(
            record
                .deadline_unix_ms
                .expect("recovery deadline is durable")
                .checked_sub(context.started_unix_ms),
            Some(
                u64::try_from(DETACHED_INDEX_TIMEOUT.as_millis())
                    .expect("recovery timeout fits public milliseconds")
            )
        );
        drop(recovery);
        let terminal = journal
            .status(operation)
            .expect("unwound recovery remains queryable");
        assert_eq!(terminal.state, OperationState::Failed);
        assert_eq!(
            terminal
                .error
                .as_ref()
                .expect("unwind reason persists")
                .code(),
            ErrorCode::Internal
        );

        drop(handle);
        actor.join().expect("journal actor joins");
    }

    #[test]
    fn pre_guard_cleanup_terminalizes_prepared_and_activated_recoveries() {
        let journal = Arc::new(OperationJournal::open_in_memory().expect("journal opens"));
        let repositories = [
            RepositoryId::from_bytes([81; 16]),
            RepositoryId::from_bytes([82; 16]),
        ];
        let generations = [
            GenerationId::from_bytes([91; 20]),
            GenerationId::from_bytes([92; 20]),
        ];
        let operations = [
            OperationId::from_bytes([101; 16]),
            OperationId::from_bytes([102; 16]),
        ];
        for ((repository, generation), operation) in
            repositories.into_iter().zip(generations).zip(operations)
        {
            let context = RepositoryOperationSubmission::new(
                repository,
                Some(generation),
                1,
                0,
                RepositoryOperationMode::Structural,
            )
            .expect("recovery context is valid");
            let submission = OperationSubmission::new(
                operation,
                OperationKind::Recovery,
                PlanHash::from_bytes([operation.as_bytes()[0]; 32]),
                ClientInstanceId::SYSTEM,
                true,
                None,
                None,
            )
            .and_then(|submission| submission.with_repository_context(context))
            .expect("recovery submission is valid");
            journal.submit(submission).expect("recovery submits");
            journal
                .start_execution(operation)
                .expect("recovery activates");
        }
        let activated = operations
            .iter()
            .map(|operation| {
                (
                    journal.status(*operation).expect("recovery is queryable"),
                    journal
                        .cancellation_token(*operation)
                        .expect("recovery cancellation is queryable"),
                )
            })
            .collect::<Vec<_>>();
        let actor = JournalActor::start(Arc::clone(&journal), 4, 4).expect("journal actor starts");
        let handle = actor.handle();
        let worker_cancellation =
            Cancellation::with_deadline(Instant::now() + Duration::from_secs(30));

        finalize_pre_guard_recovery_batch(
            &handle,
            [(repositories[0], operations[0])],
            &activated,
            &worker_cancellation,
            None,
        )
        .expect("the complete pre-guard batch terminalizes");

        assert!(operations.iter().all(|operation| {
            journal
                .status(*operation)
                .is_ok_and(|record| record.state == OperationState::Failed)
        }));
        drop(handle);
        actor.join().expect("journal actor joins");
    }

