    #[test]
    fn worker_shutdown_wins_synchronized_failure_race() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let fixture = durable_test_tempdir();
        fs::create_dir(fixture.path().join("src")).expect("source directory exists");
        fs::write(
            fixture.path().join("src/lib.rs"),
            "pub fn recovery_race() -> bool { true }\n",
        )
        .expect("source writes");
        let setup_cancellation =
            Cancellation::with_deadline(Instant::now() + Duration::from_secs(30));
        let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &setup_cancellation)
            .expect("durable service initializes");
        service
            .index_rust_fixture(fixture.path(), &setup_cancellation)
            .expect("active generation publishes");
        drop(service);
        let (_, deferred) = FirstSliceService::open_durable_deferred(2, paths.state_dir())
            .expect("deferred recovery opens");
        let targets = deferred
            .active_targets()
            .expect("active recovery targets load");
        let [target] = targets.as_slice() else {
            panic!("one active recovery target expected");
        };
        let journal = Arc::new(OperationJournal::open_in_memory().expect("journal opens"));
        let actor = JournalActor::start(Arc::clone(&journal), 4, 4).expect("journal actor starts");
        let handle = actor.handle();
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_time()
            .build()
            .expect("runtime builds");
        let worker_cancellation =
            Cancellation::with_deadline(Instant::now() + Duration::from_secs(30));
        let mut recovery =
            RecoveryOperationGuard::start(&handle, &runtime, *target, &worker_cancellation)
                .expect("recovery operation starts");
        let operation = recovery.operation();
        let barrier = Arc::new(Barrier::new(2));
        let cancellation_barrier = Arc::clone(&barrier);
        let concurrent_cancellation = worker_cancellation.clone();
        let shutdown = thread::spawn(move || {
            cancellation_barrier.wait();
            concurrent_cancellation.cancel(CancellationReason::Shutdown)
        });

        barrier.wait();
        assert!(shutdown.join().expect("shutdown thread joins"));
        recovery
            .fail(&runtime, FirstSliceError::Catalog)
            .expect("shutdown wins over worker failure");

        let record = journal
            .status(operation)
            .expect("recovery operation remains queryable");
        assert_eq!(record.state, OperationState::Cancelled);
        assert_eq!(
            record.cancellation_reason,
            Some(CancellationReason::Shutdown)
        );
        drop(recovery);
        drop(handle);
        actor.join().expect("journal actor joins");
    }

    #[test]
    fn recovery_load_retries_wait_for_consumption_and_run_once() {
        let mut schedule = RecoveryLoadSchedule::new(8);
        for index in 0..8 {
            assert_eq!(schedule.next(index == 0), Some(index));
            if index == 1 || index == 3 {
                assert!(schedule.defer_memory_retry(index));
            }
        }
        assert_eq!(schedule.next(false), None);
        assert!(!schedule.retrying);
        assert_eq!(schedule.next(true), Some(1));
        assert!(!schedule.defer_memory_retry(1));
        assert_eq!(schedule.next(false), None);
        assert_eq!(schedule.next(true), Some(3));
        assert!(!schedule.defer_memory_retry(3));
        assert_eq!(schedule.next(true), None);
        assert!(!RecoveryLoadSchedule::new(1).defer_memory_retry(0));
        assert_eq!(RecoveryLoadSchedule::new(0).next(true), None);
    }

    #[test]
    fn recovery_load_pool_rejects_overflow_and_joins_on_early_exit() {
        let stopping = AtomicBool::new(false);
        let parent = Cancellation::new();
        let completed = AtomicUsize::new(0);
        let (started, arrivals) = mpsc::sync_channel(MAX_RECOVERY_LOAD_WORKERS);
        thread::scope(|scope| {
            let mut pool = RecoveryLoadPool::<()>::new(&stopping, &parent);
            for index in 0..MAX_RECOVERY_LOAD_WORKERS {
                let child = Cancellation::new();
                let started = &started;
                let completed = &completed;
                pool.spawn(scope, index, child.clone(), move || {
                    started.send(()).unwrap();
                    loop {
                        if let Some(reason) = child.reason() {
                            assert_eq!(reason, CancellationReason::ParentCancelled);
                            completed.fetch_add(1, AtomicOrdering::Relaxed);
                            return Err(FirstSliceError::Cancelled(reason));
                        }
                        thread::park_timeout(Duration::from_millis(1));
                    }
                })
                .unwrap();
            }
            for _ in 0..MAX_RECOVERY_LOAD_WORKERS {
                arrivals.recv_timeout(Duration::from_secs(5)).unwrap();
            }
            assert!(matches!(
                pool.spawn(
                    scope,
                    MAX_RECOVERY_LOAD_WORKERS,
                    Cancellation::new(),
                    || { panic!("overflow must not spawn work") }
                ),
                Err(FirstSliceHostError::Service(FirstSliceError::Limits))
            ));
            pool.finish().unwrap();
            assert_eq!(
                completed.load(AtomicOrdering::Relaxed),
                MAX_RECOVERY_LOAD_WORKERS
            );
        });
    }

    #[test]
    fn recovery_load_scheduler_publishes_past_a_blocked_job() {
        struct Payload<'a> {
            index: usize,
            owned: &'a AtomicUsize,
        }
        impl Drop for Payload<'_> {
            fn drop(&mut self) {
                self.owned.fetch_sub(1, AtomicOrdering::Relaxed);
            }
        }
        let count = MAX_RECOVERY_LOAD_WORKERS * 2;
        let cancellations: Vec<_> = (0..count).map(|_| Cancellation::new()).collect();
        let stopping = AtomicBool::new(false);
        let parent = Cancellation::new();
        let (release, blocked) = mpsc::sync_channel(1);
        let blocked = Mutex::new(blocked);
        let (started, arrival) = mpsc::sync_channel(1);
        let (published, publications) = mpsc::sync_channel(count);
        let owned = AtomicUsize::new(0);
        let peak = AtomicUsize::new(0);
        thread::scope(|scope| {
            let coordinator = scope.spawn(|| {
                thread::scope(|loads| {
                    let mut pool = RecoveryLoadPool::new(&stopping, &parent);
                    let mut next = 0;
                    loop {
                        while next < count && pool.has_capacity() {
                            let index = next;
                            next += 1;
                            let started = &started;
                            let blocked = &blocked;
                            let owned = &owned;
                            let peak = &peak;
                            pool.spawn(loads, index, cancellations[index].clone(), move || {
                                let current = owned.fetch_add(1, AtomicOrdering::Relaxed) + 1;
                                peak.fetch_max(current, AtomicOrdering::Relaxed);
                                let payload = Payload { index, owned };
                                if index == 0 {
                                    started.send(()).expect("blocked job announces start");
                                    blocked
                                        .lock()
                                        .unwrap()
                                        .recv_timeout(Duration::from_secs(10))
                                        .unwrap();
                                }
                                Ok(payload)
                            })
                            .unwrap();
                        }
                        let Some((_, result)) = pool.next_completed().unwrap() else {
                            break;
                        };
                        let payload = result.unwrap();
                        published.send(payload.index).unwrap();
                        drop(payload);
                    }
                    pool.finish().unwrap();
                });
            });
            arrival.recv_timeout(Duration::from_secs(5)).unwrap();
            let mut observed = BTreeSet::new();
            for _ in 1..count {
                match publications.recv_timeout(Duration::from_secs(2)) {
                    Ok(index) => {
                        observed.insert(index);
                    }
                    Err(_) => break,
                }
            }
            // Release and join even when the progress assertion fails.
            release.send(()).unwrap();
            coordinator.join().unwrap();
            assert_eq!(observed, (1..count).collect());
        });
        assert_eq!(owned.load(AtomicOrdering::Relaxed), 0);
        assert!(peak.load(AtomicOrdering::Relaxed) <= MAX_RECOVERY_LOAD_WORKERS);
    }

    #[test]
    fn recovery_load_batch_overlaps_bounded_work_and_joins_before_return() {
        let cancellations: Vec<_> = (0..MAX_RECOVERY_LOAD_WORKERS)
            .map(|_| Cancellation::new())
            .collect();
        let stopping = AtomicBool::new(false);
        let parent = Cancellation::new();
        let (started, arrivals) = mpsc::sync_channel(MAX_RECOVERY_LOAD_WORKERS);
        let (releases, waits): (Vec<_>, Vec<_>) = (0..MAX_RECOVERY_LOAD_WORKERS)
            .map(|_| {
                let (send, receive) = mpsc::sync_channel(1);
                (send, Mutex::new(receive))
            })
            .unzip();
        let completed = AtomicUsize::new(0);
        thread::scope(|scope| {
            let coordinator = scope.spawn(|| {
                run_recovery_load_batch(&cancellations, &stopping, &parent, |index| {
                    started.send(index).expect("start notification fits");
                    waits[index]
                        .lock()
                        .expect("release receiver locks")
                        .recv_timeout(Duration::from_secs(5))
                        .expect("all workers start before release");
                    completed.fetch_add(1, AtomicOrdering::Relaxed);
                    Ok(index)
                })
            });
            let observed: BTreeSet<_> = (0..MAX_RECOVERY_LOAD_WORKERS)
                .map(|_| {
                    arrivals
                        .recv_timeout(Duration::from_secs(5))
                        .expect("bounded workers overlap")
                })
                .collect();
            assert_eq!(observed, (0..MAX_RECOVERY_LOAD_WORKERS).collect());
            assert_eq!(completed.load(AtomicOrdering::Relaxed), 0);
            for release in releases.iter().rev() {
                release.send(()).expect("worker is waiting");
            }
            let results = coordinator
                .join()
                .expect("coordinator joins")
                .expect("batch succeeds");
            assert_eq!(
                results,
                (0..MAX_RECOVERY_LOAD_WORKERS)
                    .map(|index| (index, Ok(index)))
                    .collect::<Vec<_>>()
            );
        });
        assert_eq!(
            completed.load(AtomicOrdering::Relaxed),
            MAX_RECOVERY_LOAD_WORKERS
        );
        let oversized: Vec<_> = (0..=MAX_RECOVERY_LOAD_WORKERS)
            .map(|_| Cancellation::new())
            .collect();
        assert!(matches!(
            run_recovery_load_batch::<()>(&oversized, &stopping, &parent, |_| {
                panic!("oversized batches must not start payload work");
            }),
            Err(FirstSliceHostError::Service(FirstSliceError::Limits))
        ));
    }

    #[test]
    fn recovery_load_batch_propagates_shutdown_and_joins_cancelled_workers() {
        let cancellations: Vec<_> = (0..MAX_RECOVERY_LOAD_WORKERS)
            .map(|_| Cancellation::with_deadline(Instant::now() + Duration::from_secs(5)))
            .collect();
        let stopping = AtomicBool::new(false);
        let parent = Cancellation::new();
        let completed = AtomicUsize::new(0);
        let (started, arrivals) = mpsc::sync_channel(MAX_RECOVERY_LOAD_WORKERS);
        thread::scope(|scope| {
            let coordinator = scope.spawn(|| {
                run_recovery_load_batch::<()>(&cancellations, &stopping, &parent, |index| {
                    started.send(()).expect("start notification fits");
                    loop {
                        if let Some(reason) = cancellations[index].reason() {
                            completed.fetch_add(1, AtomicOrdering::Relaxed);
                            return Err(FirstSliceError::Cancelled(reason));
                        }
                        thread::park_timeout(Duration::from_millis(1));
                    }
                })
            });
            for _ in &cancellations {
                arrivals
                    .recv_timeout(Duration::from_secs(5))
                    .expect("worker starts");
            }
            stopping.store(true, Ordering::Release);
            let results = coordinator
                .join()
                .expect("coordinator joins")
                .expect("cancellation is a typed result");
            assert!(results.iter().all(|(_, result)| matches!(
                result,
                Err(FirstSliceError::Cancelled(CancellationReason::Shutdown))
            )));
        });
        assert_eq!(completed.load(AtomicOrdering::Relaxed), cancellations.len());
    }

    #[test]
    fn recovery_load_batch_observes_later_panic_and_drains_earlier_worker() {
        let cancellations: Vec<_> = (0..2)
            .map(|_| Cancellation::with_deadline(Instant::now() + Duration::from_secs(5)))
            .collect();
        let stopping = AtomicBool::new(false);
        let parent = Cancellation::new();
        let completed = AtomicUsize::new(0);
        let result = run_recovery_load_batch::<()>(&cancellations, &stopping, &parent, |index| {
            if index == 1 {
                panic!("injected recovery load failure");
            }
            loop {
                if let Some(reason) = cancellations[index].reason() {
                    assert_eq!(reason, CancellationReason::ParentCancelled);
                    completed.fetch_add(1, AtomicOrdering::Relaxed);
                    return Err(FirstSliceError::Cancelled(reason));
                }
                thread::park_timeout(Duration::from_millis(1));
            }
        });
        assert!(matches!(result, Err(FirstSliceHostError::ThreadPanicked)));
        assert_eq!(completed.load(AtomicOrdering::Relaxed), 1);
    }

    #[test]
    fn recovery_load_batch_orders_memory_rejections_after_owned_payloads() {
        struct Payload<'a>(&'a AtomicUsize);
        impl Drop for Payload<'_> {
            fn drop(&mut self) {
                self.0.fetch_sub(1, AtomicOrdering::Relaxed);
            }
        }
        let live = AtomicUsize::new(0);
        let memory_error = FirstSliceError::GenerationMemoryLimit {
            breakdown: rootlight_service::GenerationMemoryBreakdown {
                retained_bytes: 0,
                reserved_bytes: 1,
                owned_bytes: 0,
                referenced_bytes: 0,
                mapped_bytes: 0,
                staged_bytes: 1,
                shared_bytes: 0,
            },
            observed: 2,
            limit: 1,
        };
        let results = run_recovery_load_batch(
            &[Cancellation::new(), Cancellation::new()],
            &AtomicBool::new(false),
            &Cancellation::new(),
            |index| {
                if index == 0 {
                    return Err(memory_error);
                }
                live.fetch_add(1, AtomicOrdering::Relaxed);
                Ok(Payload(&live))
            },
        )
        .expect("batch joins");
        assert_eq!(live.load(AtomicOrdering::Relaxed), 1);
        for (index, result) in results {
            match result {
                Ok(payload) => {
                    assert_eq!(index, 1);
                    drop(payload);
                }
                Err(error) => {
                    assert_eq!(error, memory_error);
                    assert_eq!(live.load(AtomicOrdering::Relaxed), 0);
                }
            }
        }
        let failed = run_recovery_load_batch(
            &[Cancellation::new(), Cancellation::new()],
            &AtomicBool::new(false),
            &Cancellation::new(),
            |index| {
                if index == 0 {
                    panic!("injected sibling failure after payload admission");
                }
                live.fetch_add(1, AtomicOrdering::Relaxed);
                Ok(Payload(&live))
            },
        );
        assert!(matches!(failed, Err(FirstSliceHostError::ThreadPanicked)));
        assert_eq!(live.load(AtomicOrdering::Relaxed), 0);
    }

    fn run_recovery_worker_with_start_hook(
        repository_count: usize,
        after_start: RecoveryWorkerStartHook,
        after_active_restore: Option<RecoveryWorkerCheckpointHook>,
    ) -> (
        Result<(), FirstSliceHostError>,
        Vec<OperationRecord>,
        Vec<RepositoryOperationContext>,
        bool,
        bool,
        HealthStatus,
    ) {
        run_recovery_worker_with_shutdown_hook(
            repository_count,
            after_start,
            after_active_restore,
            None,
        )
    }

    fn run_recovery_worker_with_shutdown_hook(
        repository_count: usize,
        after_start: RecoveryWorkerStartHook,
        after_active_restore: Option<RecoveryWorkerCheckpointHook>,
        shutdown_interrupt_count: Option<usize>,
    ) -> (
        Result<(), FirstSliceHostError>,
        Vec<OperationRecord>,
        Vec<RepositoryOperationContext>,
        bool,
        bool,
        HealthStatus,
    ) {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let fixture = durable_test_tempdir();
        let setup_cancellation =
            Cancellation::with_deadline(Instant::now() + Duration::from_secs(30));
        let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &setup_cancellation)
            .expect("durable service initializes");
        for index in 0..repository_count {
            let repository = fixture.path().join(format!("repository-{index}"));
            fs::create_dir_all(repository.join("src")).expect("source directory exists");
            fs::write(
                repository.join("src/lib.rs"),
                format!("pub fn recovery_terminalization_{index}() -> bool {{ true }}\n"),
            )
            .expect("source writes");
            service
                .index_rust_fixture(&repository, &setup_cancellation)
                .expect("active generation publishes");
        }
        drop(service);
        let (service, restore) = FirstSliceService::open_durable_deferred(2, paths.state_dir())
            .expect("deferred recovery opens");
        let targets = restore
            .active_targets()
            .expect("active recovery targets load");
        assert_eq!(targets.len(), repository_count);
        let recovering_repositories = targets
            .iter()
            .map(|target| {
                (
                    target.repository(),
                    RepositoryRecoveryState {
                        generation: target.generation(),
                        operation: None,
                        phase: RepositoryRecoveryPhase::ActiveGeneration,
                        current: false,
                    },
                )
            })
            .collect();
        let (refinement, _refinement_receiver) = mpsc::sync_channel(1);
        let recovery_ready = Arc::new(AtomicBool::new(false));
        let recovery_complete = Arc::new(AtomicBool::new(false));
        let state = Arc::new(DaemonState::starting());
        let lanes = FirstSliceServiceLanes {
            service: Arc::new(RwLock::new(service)),
            index_serialization: Arc::new(Mutex::new(())),
            semantic_refinements: Arc::new(Mutex::new(BTreeMap::new())),
            graph_projections: Arc::new(Mutex::new(GraphProjectionRegistry::new())),
            refinement,
            recovery_ready: Arc::clone(&recovery_ready),
            recovery_complete: Arc::clone(&recovery_complete),
            recovery_admission_ready: Arc::new(AtomicBool::new(false)),
            recovering_repositories: Arc::new(RwLock::new(recovering_repositories)),
            recovery_demand: Arc::new(Mutex::new(RecoveryDemandQueue::default())),
            support_state: Some(Arc::clone(&state)),
        };
        let journal = Arc::new(OperationJournal::open_in_memory().expect("journal opens"));
        let actor = JournalActor::start(Arc::clone(&journal), 4, 4).expect("journal actor starts");
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_time()
            .build()
            .expect("runtime builds");
        let starting_state = Arc::clone(&state);
        let after_start: RecoveryWorkerStartHook = Box::new(move |cancellation, stopping| {
            assert_eq!(starting_state.lifecycle(), DaemonLifecycle::Starting);
            after_start(cancellation, stopping)
        });
        let stopping = Arc::new(AtomicBool::new(false));
        if shutdown_interrupt_count.is_some() || repository_count > 1 {
            let target = targets.first().expect("shutdown fixture has active work");
            lanes
                .recovery_demand
                .lock()
                .expect("demand queue locks")
                .insert(target.repository());
        }
        let handle = actor.handle();
        let mut actor = Some(actor);
        let after_active_restore = if let Some(count) = shutdown_interrupt_count {
            assert!(after_active_restore.is_none());
            let shutdown_actor = actor.take().expect("shutdown owns the actor");
            let shutdown_journal = Arc::clone(&journal);
            let shutdown_stopping = Arc::clone(&stopping);
            Some(Box::new(
                move |_: &FirstSliceServiceLanes,
                      cancellation: &Cancellation,
                      _: ServiceRequestResources<'_>| {
                    shutdown_stopping.store(true, Ordering::Release);
                    assert!(cancellation.cancel(CancellationReason::Shutdown));
                    shutdown_journal
                        .interrupt_nonterminal(count)
                        .expect("bounded shutdown interruption succeeds");
                    shutdown_actor
                        .join()
                        .expect("journal closes before recovery cleanup");
                    Ok(())
                },
            ) as RecoveryWorkerCheckpointHook)
        } else {
            after_active_restore
        };
        let result = durable_recovery_worker(
            DeferredRecoveryWork {
                restore,
                installed_generations: BTreeSet::new(),
                restore_active: true,
                targets,
                after_start: Some(after_start),
                after_active_restore,
            },
            lanes,
            handle,
            Arc::new(Mutex::new(OperationMetadataSet::new(4))),
            stopping,
            runtime,
            Cancellation::with_deadline(Instant::now() + Duration::from_secs(30)),
        );
        let contexts = journal
            .repository_operation_contexts()
            .expect("recovery contexts remain queryable");
        assert_eq!(contexts.len(), repository_count);
        let records = contexts
            .iter()
            .map(|context| {
                journal
                    .status(context.operation)
                    .expect("recovery operation remains queryable")
            })
            .collect();
        let generation_status = ControlService::with_state(
            Arc::clone(&journal),
            [104; 16],
            state,
            DaemonLimits::default(),
        )
        .health()
        .generation_status;
        if let Some(actor) = actor {
            actor.join().expect("journal actor joins");
        }
        (
            result,
            records,
            contexts,
            recovery_ready.load(Ordering::Acquire),
            recovery_complete.load(Ordering::Acquire),
            generation_status,
        )
    }

    #[test]
    fn worker_failure_terminalizes_started_recovery() {
        let (result, records, _, recovery_ready, recovery_complete, generation_status) =
            run_recovery_worker_with_start_hook(
                1,
                Box::new(|_, _| Err(FirstSliceHostError::ThreadPanicked)),
                None,
            );
        let [record] = records.as_slice() else {
            panic!("one recovery operation expected");
        };

        assert!(matches!(result, Err(FirstSliceHostError::ThreadPanicked)));
        assert_eq!(record.kind, OperationKind::Recovery);
        assert_eq!(record.state, OperationState::Failed);
        assert_eq!(
            record
                .error
                .as_ref()
                .expect("worker failure persists")
                .code(),
            ErrorCode::Internal
        );
        assert!(!recovery_ready);
        assert!(recovery_complete);
        assert_eq!(generation_status, HealthStatus::Degraded);
    }

    #[test]
    fn recovery_batches_publish_every_repository_with_terminal_journal_evidence() {
        let count = MAX_RECOVERY_LOAD_WORKERS * 2 + 1;
        let (result, records, contexts, ready, complete, health) =
            run_recovery_worker_with_start_hook(count, Box::new(|_, _| Ok(())), None);
        result.expect("multiple batches recover");
        assert_eq!(records.len(), count);
        assert_eq!(contexts.len(), count);
        assert_eq!(
            contexts
                .iter()
                .map(|context| context.repository)
                .collect::<BTreeSet<_>>()
                .len(),
            count
        );
        for (record, context) in records.iter().zip(&contexts) {
            assert_eq!(record.operation, context.operation);
            assert_eq!(record.state, OperationState::Succeeded);
            assert_eq!(
                record.progress,
                Progress::new(2, 2).expect("both phases complete")
            );
            assert!(record.error.is_none());
            assert_eq!(context.files_examined, 1);
            assert!(context.bytes_examined > 0);
        }
        assert!(ready && complete);
        assert_eq!(health, HealthStatus::Healthy);
    }

    #[test]
    fn read_ready_repositories_expose_retained_recovery_beyond_metadata_capacity() {
        let count = MAX_RECOVERY_LOAD_WORKERS * 2 + 1;
        let (result, records, _, ready, complete, _) = run_recovery_worker_with_start_hook(
            count,
            Box::new(|_, _| Ok(())),
            Some(Box::new(move |lanes, _, resources| {
                assert!(lanes.recovery_ready.load(Ordering::Acquire));
                assert!(!lanes.recovery_complete.load(Ordering::Acquire));
                let recoveries = lanes
                    .recovering_repositories
                    .read()
                    .expect("recovery map reads")
                    .clone();
                assert_eq!(recoveries.len(), count);
                assert!(count > resources.metadata.lock().expect("metadata locks").maximum);
                for (repository, recovery) in recoveries {
                    assert_eq!(recovery.phase, RepositoryRecoveryPhase::RetainedHistory);
                    for include_operations in [true, false] {
                        let deadline = Instant::now() + Duration::from_secs(5);
                        let context = FirstSliceIpcContext {
                            client_instance_id: ClientInstanceId::from_bytes([7; 16]),
                            selected_protocol_minor: PROTOCOL_MINOR,
                            cancellation: Cancellation::with_deadline(deadline),
                            deadline,
                            effective_budget: None,
                            index_admission: None,
                        };
                        let mut request = status_request(repository, Some(recovery.generation));
                        request.include_operations = include_operations;
                        let response = execute_service_request(
                            lanes,
                            resources,
                            FirstSliceIpcRequest::RepositoryStatus(request),
                            context.clone(),
                            &mut None,
                        )
                        .expect("active generation remains readable during retained recovery");
                        let FirstSliceIpcResponse::RepositoryStatus(status) = response else {
                            panic!("repository status expected");
                        };
                        assert_eq!(
                            parse_generation(status.resolved_generation.as_ref()).unwrap(),
                            recovery.generation
                        );
                        assert_eq!(status.state, "indexing");
                        if include_operations {
                            let operations = status
                                .operations
                                .iter()
                                .filter(|operation| {
                                    operation.kind == daemon::OperationKind::Recovery as i32
                                })
                                .collect::<Vec<_>>();
                            assert_eq!(operations.len(), 1);
                            let operation = operations[0];
                            assert_eq!(
                                Some(parse_operation(operation.operation.as_ref()).unwrap()),
                                recovery.operation
                            );
                            assert_eq!(operation.state, daemon::OperationState::Running as i32);
                            assert_eq!((operation.completed_units, operation.total_units), (1, 2));
                            assert!(!operation.owned_by_client);
                            assert!(operation.started_unix_ms > 0);
                            let mut bounded = status.clone();
                            bounded
                                .operations
                                .extend((0..MAX_PUBLIC_REPOSITORY_OPERATIONS).map(|index| {
                                    daemon::RepositoryStatusOperation {
                                        operation: Some(operation_to_wire(
                                            OperationId::from_bytes(
                                                [u8::try_from(index)
                                                    .expect("bounded fixture ordinal");
                                                    16],
                                            ),
                                        )),
                                        kind: daemon::OperationKind::RepositoryIndex as i32,
                                        started_unix_ms: u64::MAX,
                                        ..Default::default()
                                    }
                                }));
                            project_current_recovery(
                                &mut bounded,
                                recovery.operation.expect("recovery identity"),
                                true,
                                resources,
                                &context,
                            )
                            .expect("recovery projection remains bounded");
                            assert_eq!(bounded.operations.len(), MAX_PUBLIC_REPOSITORY_OPERATIONS);
                            assert_eq!(
                                bounded
                                    .operations
                                    .iter()
                                    .filter(
                                        |item| item.kind == daemon::OperationKind::Recovery as i32
                                    )
                                    .count(),
                                1
                            );
                            assert!(
                                bounded
                                    .operations
                                    .windows(2)
                                    .all(|items| items[0].started_unix_ms
                                        >= items[1].started_unix_ms)
                            );
                        } else {
                            assert!(status.operations.is_empty());
                        }
                    }
                }
                Ok(())
            })),
        );
        result.expect("recovery finishes after the read-ready checkpoint");
        assert!(ready && complete);
        assert!(
            records
                .iter()
                .all(|record| record.state == OperationState::Succeeded)
        );
    }

    #[test]
    fn successful_recovery_reports_both_durable_phases_complete() {
        let (result, records, contexts, recovery_ready, recovery_complete, generation_status) =
            run_recovery_worker_with_start_hook(1, Box::new(|_, _| Ok(())), None);
        let [record] = records.as_slice() else {
            panic!("one recovery operation expected");
        };
        let [context] = contexts.as_slice() else {
            panic!("one recovery context expected");
        };

        result.expect("recovery completes");
        assert_eq!(record.kind, OperationKind::Recovery);
        assert_eq!(record.state, OperationState::Succeeded);
        assert!(record.deadline_unix_ms.is_some());
        assert!(record.peak_rss_bytes > 0);
        assert_eq!(record.written_bytes, 0);
        assert_eq!(context.files_examined, 1);
        assert!(context.bytes_examined > 0);
        assert_eq!(
            record.progress,
            Progress::new(2, 2).expect("terminal recovery progress is valid")
        );
        assert!(recovery_ready);
        assert!(recovery_complete);
        assert_eq!(generation_status, HealthStatus::Healthy);
    }

    #[test]
    fn shutdown_terminalizes_started_recovery_as_cancelled() {
        let (result, records, _, _, _, _) = run_recovery_worker_with_start_hook(
            2,
            Box::new(|cancellation, stopping| {
                stopping.store(true, Ordering::Release);
                let _ = cancellation.cancel(CancellationReason::Shutdown);
                Ok(())
            }),
            None,
        );

        result.expect("shutdown drains recovery worker");
        assert!(records.iter().all(|record| {
            record.kind == OperationKind::Recovery
                && record.state == OperationState::Cancelled
                && record.cancellation_reason == Some(CancellationReason::Shutdown)
        }));
    }

    #[test]
    fn shutdown_finalizes_unstarted_retained_work_without_actor_admission() {
        for interrupted in 0..=2 {
            let (result, records, contexts, ready, complete, _) =
                run_recovery_worker_with_shutdown_hook(
                    2,
                    Box::new(|_, _| Ok(())),
                    None,
                    Some(interrupted),
                );
            result.expect("unstarted retained work uses direct terminalization after shutdown");
            assert!(ready);
            assert!(!complete);
            assert_eq!(records.len(), 2);
            assert_eq!(
                records
                    .iter()
                    .filter(|record| record.state == OperationState::Interrupted)
                    .count(),
                interrupted
            );
            assert!(records.iter().all(|record| {
                record.state == OperationState::Interrupted
                    || (record.state == OperationState::Cancelled
                        && record.cancellation_reason == Some(CancellationReason::Shutdown))
            }));
            assert!(records.iter().all(|record| {
                record.peak_rss_bytes > 0
                    && record.progress == Progress::new(1, 2).expect("active phase completed")
            }));
            assert!(
                contexts
                    .iter()
                    .all(|context| context.files_examined == 1 && context.bytes_examined > 0)
            );
        }
    }

    #[test]
    fn retained_restore_interruption_terminalizes_before_recovery_completes() {
        let (result, records, _, recovery_ready, recovery_complete, generation_status) =
            run_recovery_worker_with_start_hook(
                1,
                Box::new(|_, _| Ok(())),
                Some(Box::new(|lanes, cancellation, _| {
                    assert!(lanes.recovery_ready.load(Ordering::Acquire));
                    assert!(!lanes.recovery_complete.load(Ordering::Acquire));
                    assert_eq!(
                        lanes
                            .support_state
                            .as_deref()
                            .expect("recovery publishes support state")
                            .lifecycle(),
                        DaemonLifecycle::Ready
                    );
                    let recoveries = lanes
                        .recovering_repositories
                        .read()
                        .expect("recovery set reads");
                    assert_eq!(recoveries.len(), 1);
                    assert!(
                        recoveries
                            .values()
                            .all(|recovery| recovery.phase
                                == RepositoryRecoveryPhase::RetainedHistory)
                    );
                    drop(recoveries);
                    let service = lanes.service.read().expect("recovered service reads");
                    let repositories = service.list_repositories();
                    assert_eq!(repositories.len(), 1);
                    let inventory = service
                        .support_inventory_snapshot_from_accounting()
                        .expect("reconciled support inventory reads")
                        .expect("active recovery publishes authoritative accounting");
                    assert_eq!(
                        inventory.storage_accounting_state,
                        FirstSliceStorageAccountingState::Reconciled
                    );
                    assert!(cancellation.cancel(CancellationReason::ClientRequest));
                    Ok(())
                })),
            );

        result.expect("retained interruption is a terminal degraded outcome");
        let [record] = records.as_slice() else {
            panic!("one recovery operation expected");
        };
        assert_eq!(record.state, OperationState::Cancelled);
        assert_eq!(
            record.cancellation_reason,
            Some(CancellationReason::ClientRequest)
        );
        assert_eq!(
            record.progress,
            Progress::new(1, 2).expect("retained recovery progress is valid")
        );
        assert!(recovery_ready);
        assert!(recovery_complete);
        assert_eq!(generation_status, HealthStatus::Degraded);
    }

    #[test]
    fn terminal_retained_recovery_releases_busy_admission() {
        for (reason, expected_state) in [
            (
                Some(CancellationReason::DeadlineExceeded),
                OperationState::Interrupted,
            ),
            (
                Some(CancellationReason::ClientRequest),
                OperationState::Cancelled,
            ),
            (None, OperationState::Failed),
        ] {
            let observed_lanes = Arc::new(Mutex::new(None));
            let captured_lanes = Arc::clone(&observed_lanes);
            let (result, records, contexts, ready, complete, health) =
                run_recovery_worker_with_start_hook(
                    2,
                    Box::new(|_, _| Ok(())),
                    Some(Box::new(move |lanes, cancellation, _| {
                        *captured_lanes.lock().expect("observation locks") = Some(lanes.clone());
                        let repositories = lanes
                            .recovering_repositories
                            .read()
                            .expect("recoveries read");
                        let mut demand = lanes.recovery_demand.lock().expect("demand locks");
                        for repository in repositories.keys() {
                            demand.insert(*repository);
                        }
                        if let Some(reason) = reason {
                            assert!(cancellation.cancel(reason));
                            Ok(())
                        } else {
                            Err(FirstSliceHostError::ThreadPanicked)
                        }
                    })),
                );
            if reason.is_some() {
                result.expect("cancelled recovery completes degraded");
            } else {
                assert!(matches!(result, Err(FirstSliceHostError::ThreadPanicked)));
            }
            assert!(ready && complete);
            assert_eq!(health, HealthStatus::Degraded);
            for record in &records {
                assert_eq!(record.kind, OperationKind::Recovery);
                assert_eq!(record.state, expected_state);
                assert_eq!(
                    record.progress,
                    Progress::new(1, 2).expect("active phase finished")
                );
            }
            let lanes = observed_lanes
                .lock()
                .expect("observation locks")
                .take()
                .expect("active recovery was observed");
            assert!(
                lanes
                    .recovering_repositories
                    .read()
                    .expect("recoveries read")
                    .is_empty(),
                "terminal operations must not remain in the operation.status BUSY fast path"
            );
            assert!(
                lanes
                    .recovery_demand
                    .lock()
                    .expect("demand locks")
                    .repositories
                    .is_empty()
            );
            for context in contexts {
                guard_repository_index_recovery(&lanes, Some(context.repository))
                    .expect("terminal recovery no longer blocks repository admission");
            }
        }
    }

    #[test]
    fn recovery_failure_after_active_restore_keeps_last_good_generation_available() {
        let (result, records, _, recovery_ready, recovery_complete, generation_status) =
            run_recovery_worker_with_start_hook(
                1,
                Box::new(|_, _| Ok(())),
                Some(Box::new(|lanes, _, _| {
                    assert!(!lanes.recovery_complete.load(Ordering::Acquire));
                    assert_eq!(
                        lanes
                            .support_state
                            .as_deref()
                            .expect("recovery publishes support state")
                            .lifecycle(),
                        DaemonLifecycle::Ready
                    );
                    assert_eq!(
                        lanes
                            .service
                            .read()
                            .expect("recovered service reads")
                            .list_repositories()
                            .len(),
                        1
                    );
                    Err(FirstSliceHostError::Service(FirstSliceError::Catalog))
                })),
            );

        assert!(matches!(
            result,
            Err(FirstSliceHostError::Service(FirstSliceError::Catalog))
        ));
        let [record] = records.as_slice() else {
            panic!("one recovery operation expected");
        };
        assert_eq!(record.state, OperationState::Failed);
        assert!(recovery_ready);
        assert!(recovery_complete);
        assert_eq!(generation_status, HealthStatus::Degraded);
    }

